// deductBalances atomically checks all balances then deducts them.
// Panics if any balance is insufficient — no partial deductions.
// costs is a slice of [coinId, amount] pairs.
func deductBalances(caller string, costs [][2]string) {
	// First pass: verify all sufficient
	for _, pair := range costs {
		coinId, amtStr := pair[0], pair[1]
		required, err := strconv.ParseUint(amtStr, 10, 64)
		if err != nil || required == 0 {
			continue
		}
		balKey := caller + ":" + coinId
		have := uint64(0)
		if balances.Has(balKey) {
			have, _ = strconv.ParseUint(balances.Get(balKey).(string), 10, 64)
		}
		if have < required {
			panic("insufficient " + coinId + ": need " + amtStr + " have " + strconv.FormatUint(have, 10))
		}
	}
	// Second pass: deduct all
	for _, pair := range costs {
		coinId, amtStr := pair[0], pair[1]
		required, err := strconv.ParseUint(amtStr, 10, 64)
		if err != nil || required == 0 {
			continue
		}
		balKey := caller + ":" + coinId
		current, _ := strconv.ParseUint(balances.Get(balKey).(string), 10, 64)
		balances.Set(balKey, strconv.FormatUint(current-required, 10))
	}
}

func splitJsonArray(s string) []string {
	var result []string
	depth, start := 0, 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				if e := strings.TrimSpace(s[start:i]); e != "" {
					result = append(result, e)
				}
				start = i + 1
			}
		}
	}
	if e := strings.TrimSpace(s[start:]); e != "" {
		result = append(result, e)
	}
	return result
}

// Package fenwick is an order-statistic Fenwick (binary indexed) tree over
// non-negative int64 weights, backed by avl.Tree so it can live in realm
// state.
//
// It exists to answer one question in O(log N): given a random unit k drawn
// from [0, Total()), which index owns that unit? That is the weighted-raffle
// draw — each index's value is its ticket count, and Select maps a ticket
// number to its owner. The naive version of that answer walks every index
// accumulating values until the running total passes k, which is O(N) and
// will eventually exceed a block's gas limit. Select never walks: it descends
// the tree's binary structure, touching at most ~log2(N) nodes.
//
// DESIGN DECISION — negative deltas are rejected, not supported. Add panics
// on a negative delta and Append panics on a negative initial value. This
// structure is append-and-grow only. The reason is that Select is only
// meaningful while prefix sums are monotonically non-decreasing: with a
// negative value somewhere, "the index owning unit k" is not well defined and
// the binary descent would silently return a wrong owner rather than fail.
// Refusing the input loudly is the only honest option, so a caller that needs
// decreasing weights gets a panic instead of a corrupt draw. The rest of the
// structure (Add, Append, Total, ValueAt, Len) is otherwise a general,
// reusable Fenwick tree.
//
// Complexity: Append O(log N), Add O(log N), Select O(log N), Total O(1),
// ValueAt O(log N) (one avl lookup), Len O(1).
package fenwick

import (
	"math/bits"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// keyWidth is enough decimal digits for any non-negative int64 (max is
// 9223372036854775807, 19 digits). Keys are fixed-width and zero-padded so
// that avl.Tree's lexicographic key order matches numeric index order; this
// mirrors roundKey in r/splash/beacon.
const keyWidth = 19

const zeroPad = "0000000000000000000"

// indexKey renders i as a fixed-width, zero-padded decimal string.
func indexKey(i int) string {
	s := strconv.Itoa(i)
	if len(s) < keyWidth {
		s = zeroPad[:keyWidth-len(s)] + s
	}
	return s
}

// Tree is an order-statistic Fenwick tree.
//
// Storage is two avl.Trees keyed by index (never a Go map or a slice, so that
// realm state stays deterministic and persistent):
//
//   - values holds the caller-visible value at each 0-based index.
//   - nodes holds the Fenwick partial sums, keyed by 1-based position, where
//     node j covers the value range (j-lsb(j), j].
//
// total is maintained incrementally so Total is O(1).
type Tree struct {
	values *avl.Tree
	nodes  *avl.Tree
	n      int
	total  int64
}

// NewTree returns an empty tree.
func NewTree() *Tree {
	return &Tree{
		values: avl.NewTree(),
		nodes:  avl.NewTree(),
	}
}

// Len returns the number of indices.
func (t *Tree) Len() int {
	return t.n
}

// Total returns the sum of all values. O(1).
func (t *Tree) Total() int64 {
	return t.total
}

// node reads the 1-based Fenwick node at position j. Every position in
// [1, n] is written at Append time, so a live position is always present;
// Has is still checked because avl.Get returns a single value and would
// otherwise type-assert nil on a missing key.
func (t *Tree) node(j int) int64 {
	key := indexKey(j)
	if !t.nodes.Has(key) {
		return 0
	}
	return t.nodes.Get(key).(int64)
}

func (t *Tree) setNode(j int, v int64) {
	t.nodes.Set(indexKey(j), v)
}

// ValueAt returns the value stored at index i. Panics if i is out of range.
func (t *Tree) ValueAt(i int) int64 {
	if i < 0 || i >= t.n {
		panic("fenwick: index out of range")
	}
	key := indexKey(i)
	if !t.values.Has(key) {
		return 0
	}
	return t.values.Get(key).(int64)
}

// lsb returns the lowest set bit of j (j > 0).
func lsb(j int) int {
	return j & -j
}

// Append adds a new index at the end with the given initial value and
// returns its 0-based index. Panics if value is negative: see the
// append-and-grow note in the package doc.
func (t *Tree) Append(value int64) int {
	if value < 0 {
		panic("fenwick: negative value; tree is append-and-grow only")
	}
	t.addTotal(value)

	i := t.n
	t.n++
	t.values.Set(indexKey(i), value)

	// The new 1-based position j covers (j-lsb(j), j]. Seed its node with
	// the new value plus the nodes of the children that decompose
	// (j-lsb(j), j-1], which is O(log N) reads and keeps the invariant
	// without rebuilding anything.
	j := t.n
	sum := value
	for c := j - 1; c > j-lsb(j); c -= lsb(c) {
		sum += t.node(c)
	}
	t.setNode(j, sum)
	return i
}

// Add increases the value at index i by delta. i must be in [0, Len()).
// Panics on a negative delta: this structure is append-and-grow only, and
// silently accepting a decrease would make Select return wrong owners rather
// than fail (see the package doc). A zero delta is accepted and is a no-op.
func (t *Tree) Add(i int, delta int64) {
	if i < 0 || i >= t.n {
		panic("fenwick: index out of range")
	}
	if delta < 0 {
		panic("fenwick: negative delta; tree is append-and-grow only")
	}
	if delta == 0 {
		return
	}
	t.addTotal(delta)

	key := indexKey(i)
	t.values.Set(key, t.ValueAt(i)+delta)

	for j := i + 1; j <= t.n; j += lsb(j) {
		t.setNode(j, t.node(j)+delta)
	}
}

// addTotal accumulates into total, refusing to wrap. An int64 overflow here
// would corrupt every later Select, so it is a panic and not a silent wrap.
func (t *Tree) addTotal(delta int64) {
	if t.total+delta < t.total {
		panic("fenwick: total overflows int64")
	}
	t.total += delta
}

// Prefix returns the sum of values at indices [0, i). Panics if i is outside
// [0, Len()]. O(log N).
func (t *Tree) Prefix(i int) int64 {
	if i < 0 || i > t.n {
		panic("fenwick: index out of range")
	}
	var sum int64
	for j := i; j > 0; j -= lsb(j) {
		sum += t.node(j)
	}
	return sum
}

// Select returns the index owning cumulative unit k, that is the unique i
// with Prefix(i) <= k < Prefix(i+1). Panics if k is outside [0, Total()).
// O(log N): a binary descent over the tree's node positions, never a walk
// over indices.
//
// An index whose value is 0 owns no units and is therefore never returned:
// the descent takes the largest position whose prefix is still <= k, which
// steps past any zero-valued index.
func (t *Tree) Select(k int64) int {
	if k < 0 || k >= t.total {
		panic("fenwick: k out of range")
	}

	// Start from the highest power of two <= n and halve each step.
	pos := 0
	rem := k
	for step := 1 << (bits.Len(uint(t.n)) - 1); step > 0; step >>= 1 {
		next := pos + step
		if next > t.n {
			continue
		}
		v := t.node(next)
		if v <= rem {
			pos = next
			rem -= v
		}
	}
	// pos is the count of indices whose cumulative sum is still <= k, which
	// is exactly the 0-based index owning unit k.
	return pos
}

// Package bls254 implements BLS signature verification over BN254, plus the
// hash-to-G1 construction and message encoding used by the SPLASH beacon.
//
// Curve: alt_bn128 / BN254. G1: y^2 = x^3 + 3 over Fp. Points are encoded as
// 64 bytes (x|y), each coordinate 32-byte big-endian. G2 points (as used for
// the publisher's public key and the fixed generator) are 128 bytes,
// EIP-197 wire order: x_imag | x_real | y_imag | y_real.
//
// There is no big-integer type in Gno, so field arithmetic goes through
// crypto/modexp (EIP-198 modular exponentiation) plus hand-rolled 4-limb
// compare/subtract/add for the one modular addition hash-to-G1 needs.
package bls254

import (
	"crypto/bn254"
	"crypto/modexp"
	"crypto/sha256"
	"encoding/hex"
	"math/bits"
	"strconv"
)

// DOMAIN is the hash-to-G1 domain separation tag for the SPLASH beacon.
const DOMAIN = "SPLASH-BEACON-BN254-G1-v1"

const (
	// pHex is the BN254 base field modulus, big-endian.
	pHex = "30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47"
	// sqrtExpHex is (P+1)/4, a valid modular square-root exponent because
	// P % 4 == 3.
	sqrtExpHex = "0c19139cb84c680a6e14116da060561765e05aa45a1c72a34f082305b61f3f52"
	// g2GenHex is the canonical G2 generator, EIP-197 wire order
	// (x_imag | x_real | y_imag | y_real).
	g2GenHex = "198e9393920d483a7260bfb731fb5d25f1aa493335a9e71297e485b7aef312c21800deef121f1e76426a00665e5c4479674322d4f75edadd46debd5cd992f6ed090689d0585ff075ec9e99ad690c3395bc4b313370b38ef355acdadcd122975b12c85ea5db8c6deb4aab71808dcb408fe3d1e7690c43d37b4ce6cc0166fa7daa"
)

var (
	pBytes       = mustDecodeHex(pHex)
	pLimbs       = toLimbs(pBytes)
	sqrtExpBytes = mustDecodeHex(sqrtExpHex)
	g2GenBytes   = mustDecodeHex(g2GenHex)
)

func mustDecodeHex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic("bls254: bad constant hex")
	}
	return b
}

// ---- 4-limb (256-bit) field helpers. Inputs/outputs are 32-byte big-endian. ----
//
// Every function in this block is hand-unrolled over the four limbs rather than
// written as a `for i := 0; i < 4; i++` loop. That is not style, it is the second
// largest gas item in the drand path after the field multiply itself. Measured on
// this toolchain, 100 calls with the harness baseline subtracted:
//
//	              looped    unrolled   saved
//	toLimbs       52,705      39,328     25%
//	fromLimbs     58,961      42,308     28%
//	addModP       56,287      49,420     12%
//
// The gno VM charges per interpreted operation, so the loop counter, the bound
// test and the i*8 and 3-i index arithmetic cost real gas on top of the eight
// shift-ors they schedule. halveModP in fieldmul.gno was already unrolled and
// measured 21,035 against addModP's looped 56,287 for strictly more work, which
// is what prompted this.
//
// The saving is smaller than that comparison suggested -- addModP gave back 12%,
// not the 2.5x the halveModP contrast implied, because most of its cost is the
// four bits.Add64 calls and the cmp, not the loop scaffolding. The numbers above
// are measured on this toolchain, not predicted.
//
// The unrolled bodies are mechanical transcriptions of the loops they replace;
// TestLimbHelpersUnrolledMatchLooped in bls254_test.gno keeps a copy of each
// original loop and asserts the two agree on a large operand set, so the
// transcription is checked rather than eyeballed.

func toLimbs(b []byte) [4]uint64 {
	var l [4]uint64
	l[3] = uint64(b[0])<<56 | uint64(b[1])<<48 | uint64(b[2])<<40 | uint64(b[3])<<32 |
		uint64(b[4])<<24 | uint64(b[5])<<16 | uint64(b[6])<<8 | uint64(b[7])
	l[2] = uint64(b[8])<<56 | uint64(b[9])<<48 | uint64(b[10])<<40 | uint64(b[11])<<32 |
		uint64(b[12])<<24 | uint64(b[13])<<16 | uint64(b[14])<<8 | uint64(b[15])
	l[1] = uint64(b[16])<<56 | uint64(b[17])<<48 | uint64(b[18])<<40 | uint64(b[19])<<32 |
		uint64(b[20])<<24 | uint64(b[21])<<16 | uint64(b[22])<<8 | uint64(b[23])
	l[0] = uint64(b[24])<<56 | uint64(b[25])<<48 | uint64(b[26])<<40 | uint64(b[27])<<32 |
		uint64(b[28])<<24 | uint64(b[29])<<16 | uint64(b[30])<<8 | uint64(b[31])
	return l
}

func fromLimbs(l [4]uint64) []byte {
	b := make([]byte, 32)
	v := l[3]
	b[0], b[1], b[2], b[3] = byte(v>>56), byte(v>>48), byte(v>>40), byte(v>>32)
	b[4], b[5], b[6], b[7] = byte(v>>24), byte(v>>16), byte(v>>8), byte(v)
	v = l[2]
	b[8], b[9], b[10], b[11] = byte(v>>56), byte(v>>48), byte(v>>40), byte(v>>32)
	b[12], b[13], b[14], b[15] = byte(v>>24), byte(v>>16), byte(v>>8), byte(v)
	v = l[1]
	b[16], b[17], b[18], b[19] = byte(v>>56), byte(v>>48), byte(v>>40), byte(v>>32)
	b[20], b[21], b[22], b[23] = byte(v>>24), byte(v>>16), byte(v>>8), byte(v)
	v = l[0]
	b[24], b[25], b[26], b[27] = byte(v>>56), byte(v>>48), byte(v>>40), byte(v>>32)
	b[28], b[29], b[30], b[31] = byte(v>>24), byte(v>>16), byte(v>>8), byte(v)
	return b
}

// cmp returns -1, 0, 1 for a<b, a==b, a>b. Most-significant limb first, so the
// common case of a difference in the top limb returns after one comparison.
func cmp(a, b [4]uint64) int {
	if a[3] != b[3] {
		if a[3] < b[3] {
			return -1
		}
		return 1
	}
	if a[2] != b[2] {
		if a[2] < b[2] {
			return -1
		}
		return 1
	}
	if a[1] != b[1] {
		if a[1] < b[1] {
			return -1
		}
		return 1
	}
	if a[0] != b[0] {
		if a[0] < b[0] {
			return -1
		}
		return 1
	}
	return 0
}

func sub(a, b [4]uint64) [4]uint64 {
	var r [4]uint64
	var borrow uint64
	r[0], borrow = bits.Sub64(a[0], b[0], 0)
	r[1], borrow = bits.Sub64(a[1], b[1], borrow)
	r[2], borrow = bits.Sub64(a[2], b[2], borrow)
	r[3], _ = bits.Sub64(a[3], b[3], borrow)
	return r
}

func add(a, b [4]uint64) ([4]uint64, uint64) {
	var r [4]uint64
	var carry uint64
	r[0], carry = bits.Add64(a[0], b[0], 0)
	r[1], carry = bits.Add64(a[1], b[1], carry)
	r[2], carry = bits.Add64(a[2], b[2], carry)
	r[3], carry = bits.Add64(a[3], b[3], carry)
	return r, carry
}

// addModP computes (a + b) mod P for a, b already reduced mod P.
func addModP(a, b, p [4]uint64) [4]uint64 {
	s, carry := add(a, b)
	if carry != 0 || cmp(s, p) >= 0 {
		s = sub(s, p)
	}
	return s
}

// ---- hash-to-G1 ----

// hashToG1 is the non-panicking core of HashToG1. ok is false only if the
// try-and-increment loop exhausts its bound, which does not happen for any
// message with a well-formed hash (probability of exhaustion is ~2^-64).
func hashToG1(msg []byte) (pt []byte, ok bool) {
	pt, _, ok = hashToG1WithCounter(msg)
	return pt, ok
}

// hashToG1WithCounter is hashToG1 plus the retry counter it stopped at,
// exposed for tests that check the counter against testdata/vectors.json.
func hashToG1WithCounter(msg []byte) (pt []byte, ctr int, ok bool) {
	three := [4]uint64{3, 0, 0, 0}
	for ctr := 0; ctr < 64; ctr++ {
		buf := make([]byte, 0, len(DOMAIN)+len(msg)+1)
		buf = append(buf, DOMAIN...)
		buf = append(buf, msg...)
		buf = append(buf, byte(ctr))
		h := sha256.Sum256(buf)

		x := modexp.ModExp(h[:], []byte{1}, pBytes) // reduce mod P
		x3 := modexp.ModExp(x, []byte{3}, pBytes)    // x^3 mod P
		rhs := fromLimbs(addModP(toLimbs(x3), three, pLimbs))

		y := modexp.ModExp(rhs, sqrtExpBytes, pBytes) // candidate sqrt
		y2 := modexp.ModExp(y, []byte{2}, pBytes)
		if !bytesEqual(y2, rhs) {
			continue // not a quadratic residue
		}

		yl := toLimbs(y)
		if negy := sub(pLimbs, yl); cmp(negy, yl) < 0 {
			y = fromLimbs(negy) // canonical branch: numerically smaller root
		}
		out := make([]byte, 0, 64)
		out = append(out, x...)
		out = append(out, y...)
		return out, ctr, true
	}
	return nil, 64, false
}

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// HashToG1 maps msg to a G1 point via try-and-increment. Returns 64 bytes
// (x|y). Panics if the loop exhausts its 64-attempt bound.
func HashToG1(msg []byte) []byte {
	pt, ok := hashToG1(msg)
	if !ok {
		panic("bls254: hash_to_g1 exhausted")
	}
	return pt
}

// NegateG1 returns (x, P-y) for a 64-byte G1 point. Returns nil on bad input.
func NegateG1(pt []byte) []byte {
	return negateG1(pt)
}

func negateG1(pt []byte) []byte {
	if len(pt) != 64 {
		return nil
	}
	yl := toLimbs(pt[32:64])
	var zero [4]uint64
	out := make([]byte, 64)
	copy(out[:32], pt[:32])
	if cmp(yl, zero) == 0 {
		// y == 0 has no distinct negation; leave as-is.
		copy(out[32:], pt[32:64])
		return out
	}
	copy(out[32:], fromLimbs(sub(pLimbs, yl)))
	return out
}

// Verify reports whether sig is the BLS signature over msg under pubkey.
// pubkey is 128 bytes (G2, imaginary-first), sig is 64 bytes (G1). Verify is
// total: wrong lengths, unreduced coordinates, off-curve points and an
// invalid precompile result all yield false. It never panics.
func Verify(pubkey, msg, sig []byte) bool {
	if len(pubkey) != 128 || len(sig) != 64 {
		return false
	}
	h, ok := hashToG1(msg)
	if !ok {
		return false
	}
	negH := negateG1(h)
	if negH == nil {
		return false
	}

	in := make([]byte, 0, 384)
	in = append(in, sig...)
	in = append(in, g2GenBytes...)
	in = append(in, negH...)
	in = append(in, pubkey...)
	if len(in) != 384 {
		return false
	}

	out := bn254.PairingCheck(in)
	// PairingCheck returns an empty NON-NIL slice on an invalid point or an
	// unreduced coordinate; checking length (not nilness) is load-bearing.
	if len(out) != bn254.PairingOutputSize {
		return false
	}
	return out[len(out)-1] == 1
}

// RoundMessage builds the canonical message for a beacon round:
// chainID || "|" || decimal(round).
func RoundMessage(chainID string, round int64) []byte {
	return []byte(chainID + "|" + strconv.FormatInt(round, 10))
}

package bls254

// The drand "evmnet" chain's identity: the four facts about the beacon that are
// properties of the CHAIN rather than of any code here.
//
// THIS IS THE ONE PLACE THE GROUP PUBLIC KEY IS WRITTEN DOWN. Before this file it
// appeared only in test files, duplicated across drandvectors_test.gno and
// drandgas_test.gno; both now read it from here, and r/splash/beacon decodes it
// once at init. A second copy of a verification key is a second thing to get
// wrong, and the wrong one would reject every real signature or -- far worse in a
// different scheme -- accept a forged one.
//
// IT LIVES IN THIS PURE PACKAGE, NOT IN THE REALM, because it describes drand,
// not SPLASH. The realm that consumes it is one consumer; the tests are another;
// r/splash/arcade/raffle needs PeriodSeconds for a build-time guard and must not
// have to import a realm to get it.
//
// PROVENANCE, AND IT IS NOT DOCUMENTATION. Every value below was read from
// drand's own /info endpoint and is byte-identical from three independent relays
// -- api.drand.sh, api2.drand.sh and drand.cloudflare.com. The verbatim curl
// commands and responses are recorded twice, in testdata/drand/rounds.raw.txt
// here and in r/splash/beacon/testdata/drand-rounds.raw.txt.
const (
	// DrandEvmnetChainHash identifies the chain. It is not used in verification
	// -- the signed message is keccak256(uint64 round) and nothing else -- so it
	// is here to name what a signature belongs to, and to make a wrong-chain
	// fixture obvious to a reader rather than only to the pairing check.
	DrandEvmnetChainHash = "04f1e9062b8a81f848fded9c12306733282b2727ecced50032187751166ec8c3"

	// DrandEvmnetScheme is the scheme ID, and it is the reason drandcurve.gno
	// uses SVDW and not SSWU. See DrandDST.
	DrandEvmnetScheme = "bls-bn254-unchained-on-g1"

	// DrandEvmnetPeriodSeconds is the cadence: ONE ROUND EVERY THREE SECONDS.
	//
	// THIS NUMBER IS THE ONE THAT BREAKS THINGS. The SPLASH beacon it replaces
	// ran at five minutes, so every round-denominated duration anywhere in this
	// repository was 100x wrong the moment the key changed, while still being
	// dimensionally consistent and therefore invisible to the build guards that
	// compared rounds to rounds. Any realm expressing a DURATION in rounds must
	// multiply by this constant and compare against seconds. See
	// r/splash/beacon/DRAND-MIGRATION.md section 6.
	DrandEvmnetPeriodSeconds = 3

	// DrandEvmnetGenesisTime is round 1's unix timestamp, so round r is signed at
	// DrandEvmnetGenesisTime + DrandEvmnetPeriodSeconds*(r-1).
	//
	// NO REALM ON THIS TOOLCHAIN CAN USE THIS FOR ANYTHING, and that is worth
