func recordTable(rs []Record) string {
	if len(rs) == 0 {
		return "_Nothing here yet._\n"
	}
	var b strings.Builder
	b.WriteString("| # | Work | Worker | Paid | Points |\n|---:|---|---|---:|---:|\n")
	for _, r := range rs {
		title := sanitize.TableCell(r.Title)
		if r.Voided {
			title = "~~" + title + "~~"
		}
		b.WriteString(ufmt.Sprintf("| [%d](%s:record/%d) | %s | %s | %s | %d |\n",
			r.ID, realmURL, r.ID, title, userLink(r.Worker), formatAmount(r.Amount, r.Denom), r.Points))
	}
	return b.String()
}

func latest(offset, limit int) []Record {
	var out []Record
	records.ReverseIterateByOffset(offset, limit, func(_ string, v any) bool {
		out = append(out, copyRecord(v.(*Record)))
		return false
	})
	return out
}

func userLink(addr address) string {
	if addr == "" {
		return "-"
	}
	s := addr.String()
	short := s
	if len(s) > 14 {
		short = s[:8] + "…" + s[len(s)-4:]
	}
	return "[" + short + "](" + realmURL + ":u/" + s + ")"
}

func sourceLink(r *Record) string {
	path := strings.TrimPrefix(r.Source, "gno.land")
	if r.Source == BountiesPath && r.Ref != "" {
		id := r.Ref
		if i := strings.Index(id, "/"); i >= 0 {
			id = id[:i]
		}
		return "[bounty " + sanitize.InlineText(r.Ref) + "](" + path + ":" + url.PathEscape(id) + ")"
	}
	return "[" + r.Source + "](" + path + ")"
}

func linkOrText(s string) string {
	if u := sanitize.URL(s); u != "" && (strings.HasPrefix(s, "https://") || strings.HasPrefix(s, "/")) {
		return "[" + sanitize.LinkTitle(s) + "](" + u + ")"
	}
	return sanitize.InlineText(s)
}

func formatAmount(amount int64, denom string) string {
	if denom == "ugnot" {
		return decimal(amount, 6) + " GNOT"
	}
	return strconv.FormatInt(amount, 10) + " " + sanitize.InlineText(denom)
}

func decimal(amount int64, decimals int) string {
	s := strconv.FormatInt(amount, 10)
	neg := strings.HasPrefix(s, "-")
	s = strings.TrimPrefix(s, "-")
	for len(s) <= decimals {
		s = "0" + s
	}
	whole, frac := s[:len(s)-decimals], strings.TrimRight(s[len(s)-decimals:], "0")
	if neg {
		whole = "-" + whole
	}
	if frac == "" {
		return whole
	}
	return whole + "." + frac
}

func bpsPercent(bps int64) string {
	return decimal(bps, 2) + "%"
}

func pager(route string, page, total int) string {
	pages := (total + pageSize - 1) / pageSize
	if pages <= 1 {
		return ""
	}
	var parts []string
	if page > 1 {
		parts = append(parts, ufmt.Sprintf("[← newer](%s:%s?page=%d)", realmURL, route, page-1))
	}
	parts = append(parts, ufmt.Sprintf("page %d of %d", page, pages))
	if page < pages {
		parts = append(parts, ufmt.Sprintf("[older →](%s:%s?page=%d)", realmURL, route, page+1))
	}
	return strings.Join(parts, " · ") + "\n"
}

func splitQuery(path string) (string, url.Values) {
	route, raw := path, ""
	if i := strings.Index(path, "?"); i >= 0 {
		route, raw = path[:i], path[i+1:]
	}
	q, _ := url.ParseQuery(raw)
	return strings.Trim(route, "/"), q
}

func pageOf(q url.Values) int {
	p, err := strconv.Atoi(q.Get("page"))
	if err != nil || p < 1 {
		return 1
	}
	return p
}

func notFound() string {
	return "# Not found\n\n[Back to the leaderboard](" + realmURL + ")\n"
}

// Package reputation is Guildhall's record of completed work.
//
// Every record says that a piece of work was paid for, who did it, who vouched
// for it, how much it paid and where the work lives (a PR, a realm path, a
// proposal). Records can only be written by allowlisted writer realms, the
// Guildhall bounty escrow first among them, and only at the moment escrowed
// funds are released. Each record also keeps the address whose signed
// transaction released the funds.
//
// Scores are derived from those records with the rules in
// gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/trust: a record is worth more when the people who
// approved it are themselves trusted. Any realm can consume the result with a
// single import:
//
//	import "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
//
//	func Vote(cur realm, ...) {
//		reputation.AssertScore(cur.Previous().Address(), 300)
//		...
//	}
package reputation

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"time"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/trust/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

// BountiesPath is the escrow realm allowed to write records at launch.
const BountiesPath = "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties"

const (
	maxReviewers = 16
	maxTextLen   = 300
	maxRank      = 1000
)

// entry is what a writer realm submits when work is paid for.
type entry struct {
	Worker     address
	Poster     address
	Reviewers  []address
	ShareBps   int64
	Amount     int64
	Denom      string
	Title      string
	Link       string
	Ref        string
	Arbitrated bool
}

// Record is a stored, immutable account of paid work. Only Voided can change,
// and only by the Guildhall admin.
type Record struct {
	ID            uint64
	Worker        address
	Poster        address
	Reviewers     []address
	ReviewerTrust []int64
	Points        int64
	ShareBps      int64
	Amount        int64
	Denom         string
	Title         string
	Link          string
	Ref           string
	Source        string
	SignedBy      address
	Arbitrated    bool
	Height        int64
	At            time.Time
	Voided        bool
	VoidReason    string
}

// Profile aggregates a contributor's records.
type Profile struct {
	Addr    address
	Score   int64
	Records []uint64
	Reviews []uint64
	First   time.Time
	Last    time.Time
	earned  *avl.Tree // denom -> int64
}

// Standing is a leaderboard entry.
type Standing struct {
	Addr  address
	Score int64
}

var (
	records     avl.Tree // padded id -> *Record
	lastID      uint64
	profiles    avl.Tree // address -> *Profile
	leaderboard avl.Tree // inverted score key -> address
	seeds       avl.Tree // address -> struct{}
	writers     avl.Tree // pkgpath -> struct{}
	params      = trust.DefaultParams()
	admin       *ownable.Ownable
)

// InitialAdmin owns this namespace and is the only key that can deploy here.
// It starts out as the admin; TransferAdmin can hand the role on.
const InitialAdmin address = "g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm"

func init() {
	admin = ownable.NewWithAddress(InitialAdmin)
	writers.Set(BountiesPath, struct{}{})
}

// ---------------------------------------------------------------------------
// Writing

// AddRecord stores a piece of paid work and credits the worker. It may only be
// called by an allowlisted writer realm, at the moment it releases funds.
//
// worker was paid amount of denom for work funded by poster and approved by
// reviewers. shareBps is the fraction of the milestone the worker received
// (10000 unless a dispute split it). title, link and ref describe the work:
// link points at the PR, realm path or proposal, and ref identifies the
// work within the writer realm (for bounties, "<id>/<milestone>").
func AddRecord(cur realm, worker, poster address, reviewers []address, shareBps, amount int64, denom, title, link, ref string, arbitrated bool) uint64 {
	e := entry{
		Worker:     worker,
		Poster:     poster,
		Reviewers:  reviewers,
		ShareBps:   shareBps,
		Amount:     amount,
		Denom:      denom,
		Title:      title,
		Link:       link,
		Ref:        ref,
		Arbitrated: arbitrated,
	}
	src := cur.Previous().PkgPath()
	if src == "" || !writers.Has(src) {
		panic("reputation: " + strconv.Quote(src) + " is not an allowed writer")
	}
	if err := validateEntry(e); err != nil {
		panic(err.Error())
	}

	vouchers := make([]trust.Reviewer, len(e.Reviewers))
	for i, r := range e.Reviewers {
		vouchers[i] = trust.Reviewer{Addr: r, Score: Score(r), Seed: IsSeed(r)}
	}
	res, err := trust.Evaluate(trust.Input{
		Worker:    e.Worker,
		Poster:    e.Poster,
		Reviewers: vouchers,
		ShareBps:  e.ShareBps,
	}, params)
	if err != nil {
		panic(err.Error())
	}

	lastID++
	rec := &Record{
		ID:            lastID,
		Worker:        e.Worker,
		Poster:        e.Poster,
		Reviewers:     append([]address{}, e.Reviewers...),
		ReviewerTrust: res.TrustBps,
		Points:        res.Points,
		ShareBps:      e.ShareBps,
		Amount:        e.Amount,
		Denom:         e.Denom,
		Title:         e.Title,
		Link:          e.Link,
		Ref:           e.Ref,
		Source:        src,
		SignedBy:      unsafe.OriginCaller(),
		Arbitrated:    e.Arbitrated,
		Height:        runtime.ChainHeight(),
		At:            time.Now(),
	}
	records.Set(idKey(rec.ID), rec)

	wp := getOrCreateProfile(e.Worker)
	wp.Records = append(wp.Records, rec.ID)
	addEarned(wp, e.Denom, e.Amount)
	touch(wp, rec.At)
	setScore(wp, wp.Score+rec.Points)

	seen := map[address]bool{}
	for _, r := range e.Reviewers {
		if seen[r] || r == e.Worker {
			continue
		}
		seen[r] = true
		rp := getOrCreateProfile(r)
		rp.Reviews = append(rp.Reviews, rec.ID)
		touch(rp, rec.At)
	}

	chain.Emit("GuildhallRecord",
		"id", strconv.FormatUint(rec.ID, 10),
		"worker", e.Worker.String(),
		"points", strconv.FormatInt(rec.Points, 10),
		"source", src,
		"ref", e.Ref,
	)
	return rec.ID
}

func validateEntry(e entry) error {
	if !e.Worker.IsValid() {
		return errors.New("reputation: invalid worker address")
	}
	if !e.Poster.IsValid() {
		return errors.New("reputation: invalid poster address")
	}
	if len(e.Reviewers) == 0 || len(e.Reviewers) > maxReviewers {
		return errors.New("reputation: a record needs 1..16 reviewers")
	}
	for _, r := range e.Reviewers {
		if !r.IsValid() {
			return errors.New("reputation: invalid reviewer address")
		}
	}
	if e.Amount < 0 {
		return errors.New("reputation: negative amount")
	}
	if len(e.Title) > maxTextLen || len(e.Link) > maxTextLen || len(e.Ref) > maxTextLen || len(e.Denom) > maxTextLen {
		return errors.New("reputation: field too long")
	}
	return nil
}

// ---------------------------------------------------------------------------
// Reading: the API other realms import.

// Score returns addr's current reputation score.
func Score(addr address) int64 {
	p := getProfile(addr)
	if p == nil {
		return 0
	}
	return p.Score
}

// Level returns a display name for addr's score band.
func Level(addr address) string {
	return trust.Level(Score(addr))
}

// HasScore reports whether addr's score is at least min.
func HasScore(addr address, min int64) bool {
	return Score(addr) >= min
}

// AssertScore panics unless addr's score is at least min. It is the one-line
// gate for realms that want reputation-weighted access.
func AssertScore(addr address, min int64) {
	if s := Score(addr); s < min {
		panic(ufmt.Sprintf("guildhall: reputation %d is below the required %d", s, min))
	}
}

// CompletedCount returns how many paid records addr has as a worker.
func CompletedCount(addr address) int {
	p := getProfile(addr)
	if p == nil {
		return 0
	}
	return len(p.Records)
}

// ReviewCount returns how many records addr has vouched for.
func ReviewCount(addr address) int {
	p := getProfile(addr)
	if p == nil {
		return 0
	}
	return len(p.Reviews)
}

// Earned returns the total addr has been paid in denom through records.
func Earned(addr address, denom string) int64 {
	p := getProfile(addr)
	if p == nil || p.earned == nil {
		return 0
	}
	v := p.earned.Get(denom)
	if v == nil {
		return 0
	}
	return v.(int64)
}

// IsSeed reports whether addr is a seed reviewer.
func IsSeed(addr address) bool {
	return seeds.Has(addr.String())
}

// IsWriter reports whether pkgPath may write records.
func IsWriter(pkgPath string) bool {
	return writers.Has(pkgPath)
}

// RecordCount returns the number of records ever written.
func RecordCount() int {
	return records.Size()
}

// ContributorCount returns the number of addresses with a positive score.
func ContributorCount() int {
	return leaderboard.Size()
}

// GetRecord returns a copy of the record with the given id.
func GetRecord(id uint64) (Record, bool) {
	r := getRecord(id)
	if r == nil {
		return Record{}, false
	}
	return copyRecord(r), true
}

// RecordsOf returns up to limit of addr's work records, newest first,
// skipping the first offset.
func RecordsOf(addr address, offset, limit int) []Record {
	p := getProfile(addr)
	if p == nil {
		return nil
	}
	return collect(p.Records, offset, limit)
}

// ReviewsOf returns up to limit of the records addr vouched for, newest first.
func ReviewsOf(addr address, offset, limit int) []Record {
	p := getProfile(addr)
	if p == nil {
		return nil
	}
	return collect(p.Reviews, offset, limit)
}

// Top returns the n highest scores, highest first. Ties are ordered by
// address.
func Top(n int) []Standing {
	var out []Standing
	leaderboard.Iterate("", "", func(_ string, v any) bool {
		addr := v.(address)
		out = append(out, Standing{Addr: addr, Score: Score(addr)})
		return len(out) >= n
	})
	return out
}

// Rank returns addr's 1-based leaderboard position, or 0 if unranked.
func Rank(addr address) int {
	p := getProfile(addr)
	if p == nil || p.Score <= 0 {
		return 0
	}
	key := boardKey(p.Score, addr)
	rank := 0
	leaderboard.Iterate("", key, func(_ string, _ any) bool {
		rank++
		return rank > maxRank
	})
	if rank > maxRank {
		return 0
	}
	return rank + 1
}

// Params returns the scoring parameters in force.
func Params() trust.Params {
	return params
}

// Admin returns the address allowed to curate seeds, writers and parameters.
func Admin() address {
	return admin.Owner()
}

// ---------------------------------------------------------------------------
// Governance

//
// Guildhall governs itself: the admin, and nobody else, curates seeds,
// writers, parameters and voids. No outside realm has authority here. Hand
// the role to a multisig with TransferAdmin to share it.

// AddSeed marks addr as a seed reviewer with full trust.
func AddSeed(cur realm, addr address) {
	assertAdmin(cur)
	addSeed(addr)
}

// RemoveSeed revokes addr's seed status. Existing records keep the points
// they were awarded; only future reviews are affected.
func RemoveSeed(cur realm, addr address) {
	assertAdmin(cur)
	removeSeed(addr)
}

// AddWriter allows another realm to write records.
func AddWriter(cur realm, pkgPath string) {
	assertAdmin(cur)
	addWriter(pkgPath)
}

// RemoveWriter revokes a realm's right to write records.
func RemoveWriter(cur realm, pkgPath string) {
	assertAdmin(cur)
	removeWriter(pkgPath)
}

// SetParams changes the scoring rules for future records.
func SetParams(cur realm, base, trustThreshold, trustFloorBps, selfFundedFactorBps int64) {
	assertAdmin(cur)
	setParams(newParams(base, trustThreshold, trustFloorBps, selfFundedFactorBps))
}

// VoidRecord cancels a fraudulent record and removes its points from the
// worker. Trust the worker lent to others while holding those points is not
// unwound; voiding is for correcting abuse, not rewriting history.
func VoidRecord(cur realm, id uint64, reason string) {
	assertAdmin(cur)
	checkVoid(id, reason)
	voidRecord(id, reason)
}

// TransferAdmin hands the admin key to another address, such as a multisig.
func TransferAdmin(cur realm, newAdmin address) {
	if err := admin.TransferOwnership(0, cur, newAdmin); err != nil {
		panic(err.Error())
	}
}

// RenounceAdmin gives up the admin key for good. Nothing can curate
// reputation afterwards: seeds, writers and parameters are frozen and no
// record can be voided. Prefer TransferAdmin unless that is the intent.
func RenounceAdmin(cur realm) {
	if err := admin.DropOwnership(0, cur); err != nil {
		panic(err.Error())
	}
}

func addSeed(addr address) {
	if !addr.IsValid() {
		panic("reputation: invalid address")
	}
	seeds.Set(addr.String(), struct{}{})
	chain.Emit("GuildhallSeedAdded", "addr", addr.String())
}

func removeSeed(addr address) {
	if _, ok := seeds.Remove(addr.String()); !ok {
		panic("reputation: not a seed")
	}
	chain.Emit("GuildhallSeedRemoved", "addr", addr.String())
}

func addWriter(pkgPath string) {
	if pkgPath == "" {
		panic("reputation: empty pkgpath")
	}
	writers.Set(pkgPath, struct{}{})
	chain.Emit("GuildhallWriterAdded", "pkgpath", pkgPath)
}

func removeWriter(pkgPath string) {
	if _, ok := writers.Remove(pkgPath); !ok {
		panic("reputation: not a writer")
	}
	chain.Emit("GuildhallWriterRemoved", "pkgpath", pkgPath)
}

func newParams(base, trustThreshold, trustFloorBps, selfFundedFactorBps int64) trust.Params {
	p := trust.Params{
		Base:                base,
		TrustThreshold:      trustThreshold,
		TrustFloorBps:       trustFloorBps,
		SelfFundedFactorBps: selfFundedFactorBps,
	}
	if err := p.Validate(); err != nil {
		panic(err.Error())
	}
	return p
}

func setParams(p trust.Params) {
	params = p
	chain.Emit("GuildhallParamsChanged")
}

func checkVoid(id uint64, reason string) {
	r := getRecord(id)
	if r == nil {
		panic("reputation: unknown record")
	}
	if r.Voided {
		panic("reputation: record already voided")
	}
	if reason == "" || len(reason) > maxTextLen {
		panic("reputation: a reason of 1..300 bytes is required")
	}
}

func voidRecord(id uint64, reason string) {
	checkVoid(id, reason)
	r := getRecord(id)
	r.Voided = true
	r.VoidReason = reason
	p := getProfile(r.Worker)
	setScore(p, p.Score-r.Points)
	chain.Emit("GuildhallRecordVoided", "id", strconv.FormatUint(id, 10), "reason", reason)
}

func assertAdmin(cur realm) {
	admin.AssertOwnedBy(cur.Previous().Address())
}

// ---------------------------------------------------------------------------
// Internals

func getProfile(addr address) *Profile {
	v := profiles.Get(addr.String())
	if v == nil {
		return nil
	}
	return v.(*Profile)
}

func getOrCreateProfile(addr address) *Profile {
	if p := getProfile(addr); p != nil {
		return p
	}
	p := &Profile{Addr: addr, earned: avl.NewTree()}
	profiles.Set(addr.String(), p)
	return p
}

func getRecord(id uint64) *Record {
	v := records.Get(idKey(id))
	if v == nil {
		return nil
	}
	return v.(*Record)
}

func touch(p *Profile, at time.Time) {
	if p.First.IsZero() {
		p.First = at
	}
	p.Last = at
}

func addEarned(p *Profile, denom string, amount int64) {
	cur := int64(0)
	if v := p.earned.Get(denom); v != nil {
		cur = v.(int64)
	}
	p.earned.Set(denom, cur+amount)
}

func setScore(p *Profile, score int64) {
	if p.Score > 0 {
		leaderboard.Remove(boardKey(p.Score, p.Addr))
	}
	if score < 0 {
		score = 0
	}
	p.Score = score
	if score > 0 {
		leaderboard.Set(boardKey(score, p.Addr), p.Addr)
	}
}

// boardKey sorts higher scores first under avl's ascending iteration.
func boardKey(score int64, addr address) string {
	return pad(9223372036854775807-score, 19) + ":" + addr.String()
}

func idKey(id uint64) string {
	return pad(int64(id), 12)
}

func pad(n int64, width int) string {
	s := strconv.FormatInt(n, 10)
	for len(s) < width {
		s = "0" + s
	}
	return s
}

func collect(ids []uint64, offset, limit int) []Record {
	var out []Record
	if offset < 0 {
		offset = 0
	}
	for i := len(ids) - 1 - offset; i >= 0 && len(out) < limit; i-- {
		if r := getRecord(ids[i]); r != nil {
			out = append(out, copyRecord(r))
		}
	}
	return out
}

func copyRecord(r *Record) Record {
	c := *r
	c.Reviewers = append([]address{}, r.Reviewers...)
	c.ReviewerTrust = append([]int64{}, r.ReviewerTrust...)
	return c
}

package bounties

import (
	"chain"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounty/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/jsonw/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	realmPath   = "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties"
	apiMaxLimit = 50
	apiMaxScan  = 2000
	apiMaxToken = 200
)

// renderAPI serves JSON for the web app, under Render("api/..."):
//
//	api/stats                       counts, escrow totals, council, paused
//	api/bounties?status=&tag=&page=&limit=   newest first; status "all" or empty for every bounty
//	api/bounty/<id>                 a bounty with milestones, disputes and applications
//	api/user/<address>?page=&limit= bounties an address is involved in, with roles
//	api/tokens                      registered GRC20 tokens usable for funding
func renderAPI(route string, q url.Values) string {
	parts := strings.Split(route, "/")
	switch {
	case route == "api/stats":
		return apiStats()
	case route == "api/bounties":
		return apiList(q)
	case len(parts) == 3 && parts[1] == "bounty":
		id, err := strconv.ParseUint(parts[2], 10, 64)
		if err != nil {
			return apiError("invalid id")
		}
		bn := getBounty(id)
		if bn == nil {
			return apiError("not found")
		}
		return bountyJSON(bn, true)
	case len(parts) == 3 && parts[1] == "user":
		return apiUser(address(parts[2]), q)
	case route == "api/tokens":
		return apiTokens()
	}
	return apiError("unknown endpoint")
}

func apiStats() string {
	var escrow []string
	escrowed.Iterate("", "", func(k string, v any) bool {
		if amt := v.(int64); amt > 0 {
			escrow = append(escrow, jsonw.Obj(append([]string{"amount", jsonw.Int(amt)}, denomFields(k, grc20reg.Get(k) != nil)...)...))
		}
		return false
	})
	return jsonw.Obj(
		"total", jsonw.Int(int64(bounties.Size())),
		"open", jsonw.Int(int64(statusCount[bounty.StatusOpen])),
		"active", jsonw.Int(int64(statusCount[bounty.StatusActive])),
		"completed", jsonw.Int(int64(statusCount[bounty.StatusCompleted])),
		"cancelled", jsonw.Int(int64(statusCount[bounty.StatusCancelled])),
		"escrow", jsonw.Arr(escrow),
		"council", jsonw.String(council.Owner().String()),
		"paused", jsonw.Bool(paused),
		"realmAddress", jsonw.String(chain.PackageAddress(realmPath).String()),
	)
}

func apiList(q url.Values) string {
	status := q.Get("status")
	want, filtered := bounty.ParseStatus(status)
	if status != "" && status != "all" && !filtered {
		return apiError("unknown status")
	}
	tag := strings.ToLower(q.Get("tag"))
	limit := limitOf(q)
	skip := (pageOf(q) - 1) * limit

	var items []string
	more := false
	scanned := 0
	bounties.ReverseIterate("", "", func(_ string, v any) bool {
		scanned++
		if scanned > apiMaxScan {
			more = true
			return true
		}
		bn := v.(*bounty.Bounty)
		if filtered && bn.Status != want {
			return false
		}
		if tag != "" && !hasTag(bn, tag) {
			return false
		}
		if skip > 0 {
			skip--
			return false
		}
		if len(items) == limit {
			more = true
			return true
		}
		items = append(items, bountyJSON(bn, false))
		return false
	})
	return jsonw.Obj("items", jsonw.Arr(items), "more", jsonw.Bool(more))
}

func apiUser(addr address, q url.Values) string {
	if !addr.IsValid() {
		return apiError("invalid address")
	}
	limit := limitOf(q)
	var items []string
	more := false
	if v := byUser.Get(addr.String()); v != nil {
		ids := v.(*avl.Tree)
		ids.ReverseIterateByOffset((pageOf(q)-1)*limit, limit, func(k string, _ any) bool {
			if bv := bounties.Get(k); bv != nil {
				bn := bv.(*bounty.Bounty)
				items = append(items, jsonw.Obj("bounty", bountyJSON(bn, false), "roles", jsonw.Strings(roles(bn, addr))))
			}
			return false
		})
		more = ids.Size() > pageOf(q)*limit
	}
	return jsonw.Obj("items", jsonw.Arr(items), "more", jsonw.Bool(more))
}

func apiTokens() string {
	var items []string
	grc20reg.GetRegistry().Iterate("", "", func(k string, _ any) bool {
		tok := grc20reg.Get(k)
		if tok == nil {
			return false
		}
		items = append(items, jsonw.Obj(
			"key", jsonw.String(k),
			"name", jsonw.String(tok.GetName()),
			"symbol", jsonw.String(tok.GetSymbol()),
			"decimals", jsonw.Int(int64(tok.GetDecimals())),
		))
		return len(items) >= apiMaxToken
	})
	return jsonw.Obj("items", jsonw.Arr(items))
}

func bountyJSON(bn *bounty.Bounty, full bool) string {
	ms := make([]string, len(bn.Milestones))
	for i, m := range bn.Milestones {
		fields := []string{
			"title", jsonw.String(m.Title),
			"amount", jsonw.Int(m.Amount),
			"status", jsonw.String(m.Status.String()),
		}
		if full {
			dispute := jsonw.Null
			if d := m.Dispute; d != nil {
				dispute = jsonw.Obj(
					"openedBy", jsonw.String(d.OpenedBy.String()),
					"reason", jsonw.String(d.Reason),
					"openedAt", jsonw.Time(d.OpenedAt),
					"resolved", jsonw.Bool(d.Resolved),
					"resolvedAt", jsonw.Time(d.ResolvedAt),
					"workerBps", jsonw.Int(d.WorkerBps),
					"ruling", jsonw.String(d.Ruling),
				)
			}
			fields = append(fields,
				"submission", jsonw.String(m.Submission),
				"submittedAt", jsonw.Time(m.SubmittedAt),
				"approvals", jsonw.Addresses(m.Approvals),
				"feedback", jsonw.String(m.Feedback),
				"worker", jsonw.String(m.Worker.String()),
				"paidOut", jsonw.Int(m.PaidOut),
				"refunded", jsonw.Int(m.Refunded),
				"settledAt", jsonw.Time(m.SettleAt),
				"dispute", dispute,
			)
		}
		ms[i] = jsonw.Obj(fields...)
	}

	fields := []string{
		"id", jsonw.Uint(bn.ID),
		"title", jsonw.String(bn.Title),
		"tags", jsonw.Strings(bn.Tags),
		"status", jsonw.String(bn.Status.String()),
		"poster", jsonw.String(bn.Poster.String()),
		"assignee", jsonw.String(bn.Assignee.String()),
		"total", jsonw.Int(bn.Total()),
		"escrowed", jsonw.Int(bn.Escrowed()),
		"paidOut", jsonw.Int(bn.PaidOut()),
		"applications", jsonw.Int(int64(len(bn.Applications))),
		"createdAt", jsonw.Time(bn.CreatedAt),
		"milestones", jsonw.Arr(ms),
	}
	fields = append(fields, denomFields(bn.Denom, bn.IsGRC20)...)
	if full {
		var apps []string
		for _, a := range bn.Applications {
			apps = append(apps, jsonw.Obj(
				"applicant", jsonw.String(a.Applicant.String()),
				"pitch", jsonw.String(a.Pitch),
				"at", jsonw.Time(a.At),
			))
		}
		fields = append(fields,
			"description", jsonw.String(bn.Description),
			"link", jsonw.String(bn.Link),
			"reviewers", jsonw.Addresses(bn.Reviewers),
			"quorum", jsonw.Int(int64(bn.Quorum)),
			"arbiter", jsonw.String(bn.Arbiter.String()),
			"councilArbitrated", jsonw.Bool(councilArbitrated.Has(idKey(bn.ID))),
			"council", jsonw.String(council.Owner().String()),
			"workWindowDays", jsonw.Int(int64(bn.WorkWindow.Hours()/24)),
			"assignedAt", jsonw.Time(bn.AssignedAt),
			"closedAt", jsonw.Time(bn.ClosedAt),
			"applicationList", jsonw.Arr(apps),
		)
	}
	return jsonw.Obj(fields...)
}

// denomFields describes how to display amounts of denom.
func denomFields(denom string, isGRC20 bool) []string {
	symbol, decimals := denom, 0
	switch {
	case isGRC20:
		if tok := grc20reg.Get(denom); tok != nil {
			symbol, decimals = tok.GetSymbol(), tok.GetDecimals()
		}
	case denom == "ugnot":
		symbol, decimals = "GNOT", 6
	}
	return []string{
		"denom", jsonw.String(denom),
		"isGRC20", jsonw.Bool(isGRC20),
		"symbol", jsonw.String(symbol),
		"decimals", jsonw.Int(int64(decimals)),
	}
}

func roles(bn *bounty.Bounty, addr address) []string {
	var out []string
	if bn.Poster == addr {
		out = append(out, "poster")
	}
	if bn.Assignee == addr {
		out = append(out, "assignee")
	}
	if bn.IsReviewer(addr) {
		out = append(out, "reviewer")
	}
	if bn.Arbiter == addr {
		out = append(out, "arbiter")
	}
	if bn.HasApplied(addr) && bn.Assignee != addr {
		out = append(out, "applicant")
	}
	for _, m := range bn.Milestones {
		if m.Worker == addr && bn.Assignee != addr {
			out = append(out, "contributor")
			break
		}
	}
	return out
}

func limitOf(q url.Values) int {
	n, err := strconv.Atoi(q.Get("limit"))
	if err != nil || n < 1 {
		return 20
	}
	if n > apiMaxLimit {
		return apiMaxLimit
	}
	return n
}

func apiError(msg string) string {
	return jsonw.Obj("error", jsonw.String(msg))
}

// Package bounties is Guildhall's escrowed bounty board.
//
// Anyone can post a task, fund it with GNOT (or any native coin) or any token
// in the grc20 registry, and split it into milestones. Funds sit in this
// realm until the bounty's reviewers approve a milestone, at which point the
// milestone is paid to the contributor and a record of the work is written to
// gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation. Contested milestones go to an arbiter, who
// can pay the worker, refund the poster, or split the difference.
//
// The rules live in gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounty. This realm holds the funds,
// authenticates callers, moves coins, and renders the board.
package bounties

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounty/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	"gno.land/r/nt/grc20reg/v0"
)

const maxWorkWindowDays = 365

var (
	bounties avl.Tree // padded id -> *bounty.Bounty
	lastID   uint64
	byUser   avl.Tree // address -> *avl.Tree(padded id -> struct{})
	// councilArbitrated holds the ids of bounties whose arbiter is "the
	// council" rather than a fixed address, so they follow the council if
	// it changes hands.
	councilArbitrated avl.Tree
	statusCount       = map[bounty.Status]int{}
	escrowed          avl.Tree // denom key -> int64 currently held

	council *ownable.Ownable
	paused  bool
)

// InitialCouncil owns this namespace and is the only key that can deploy
// here. It holds the council seat until TransferCouncil hands it on.
const InitialCouncil address = "g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm"

func init() {
	council = ownable.NewWithAddress(InitialCouncil)
}

// ---------------------------------------------------------------------------
// Posting

// PostBounty posts a bounty funded with the native coins sent along with the
// call. milestones is "Title=amount;Title=amount" and must add up to exactly
// what was sent; leave it empty for a single milestone worth the whole
// amount. reviewers is a comma-separated address list (empty means the poster
// reviews alone) and quorum is how many of them must approve each milestone.
// An empty arbiter delegates disputes to the Guildhall council.
func PostBounty(cur realm, title, description, link, tags, reviewers string, quorum int, milestones, arbiter string, workWindowDays int) uint64 {
	assertNotPaused()
	if !cur.Previous().IsUserCall() {
		panic("bounties: native bounties must be posted directly by a user (maketx call with -send)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Amount <= 0 {
		panic("bounties: send exactly one coin denomination to fund the bounty")
	}
	coin := sent[0]
	specs, err := bounty.ParseMilestones(milestones, coin.Amount)
	if err != nil {
		panic(err.Error())
	}
	b := newBounty(cur, coin.Denom, false, title, description, link, tags, reviewers, quorum, specs, arbiter, workWindowDays)
	if b.Total() != coin.Amount {
		panic(ufmt.Sprintf("bounties: milestones add up to %d but %d%s was sent", b.Total(), coin.Amount, coin.Denom))
	}
	return store(b)
}

// PostBountyGRC20 posts a bounty funded with a registered GRC20 token. The
// caller must first approve this realm's address for the milestone total on
// the token; this call pulls the funds into escrow.
func PostBountyGRC20(cur realm, tokenKey, title, description, link, tags, reviewers string, quorum int, milestones, arbiter string, workWindowDays int) uint64 {
	assertNotPaused()
	if grc20reg.Get(tokenKey) == nil {
		panic("bounties: unknown token " + strconv.Quote(tokenKey))
	}
	if len(unsafe.OriginSend()) > 0 && cur.Previous().IsUserCall() {
		panic("bounties: do not send native coins with a GRC20 bounty")
	}
	specs, err := bounty.ParseMilestones(milestones, 0)
	if err != nil {
		panic(err.Error())
	}
	b := newBounty(cur, tokenKey, true, title, description, link, tags, reviewers, quorum, specs, arbiter, workWindowDays)
	grc20reg.TransferFrom(0, cur, tokenKey, b.Poster, cur.Address(), b.Total())
	return store(b)
}

func newBounty(cur realm, denom string, isGRC20 bool, title, description, link, tags, reviewers string, quorum int, specs []bounty.MilestoneSpec, arbiter string, workWindowDays int) *bounty.Bounty {
	if workWindowDays < 0 || workWindowDays > maxWorkWindowDays {
		panic(ufmt.Sprintf("bounties: work window must be 0..%d days", maxWorkWindowDays))
	}
	arb := address(strings.TrimSpace(arbiter))
	if arb == "" {
		arb = council.Owner()
	}
	b, err := bounty.New(bounty.Params{
		ID:          lastID + 1,
		Poster:      cur.Previous().Address(),
		Title:       title,
		Description: description,
		Link:        strings.TrimSpace(link),
		Tags:        strings.Split(tags, ","),
		Denom:       denom,
		IsGRC20:     isGRC20,
		Reviewers:   bounty.ParseAddresses(reviewers),
		Quorum:      quorum,
		Arbiter:     arb,
		Milestones:  specs,
		WorkWindow:  time.Duration(workWindowDays) * 24 * time.Hour,
		Now:         time.Now(),
	})
	if err != nil {
		panic(err.Error())
	}
	if strings.TrimSpace(arbiter) == "" {
		councilArbitrated.Set(idKey(b.ID), struct{}{})
	}
	return b
}

func store(b *bounty.Bounty) uint64 {
	lastID = b.ID
	bounties.Set(idKey(b.ID), b)
	statusCount[b.Status]++
	addEscrow(b, b.Total())
	index(b.Poster, b.ID)
	for _, r := range b.Reviewers {
		index(r, b.ID)
	}
	index(b.Arbiter, b.ID)
	emit("BountyPosted", b,
		"poster", b.Poster.String(),
		"denom", b.Denom,
		"total", strconv.FormatInt(b.Total(), 10))
	return b.ID
}

// ---------------------------------------------------------------------------
// Working on a bounty

// Apply asks the poster to be assigned to an open bounty.
func Apply(cur realm, id uint64, pitch string) {
	b := mustGet(id)
	caller := cur.Previous().Address()
	check(b.Apply(caller, pitch, time.Now()))
	index(caller, id)
	emit("BountyApplied", b, "applicant", caller.String())
}

// Assign hands an open bounty to a contributor. Poster only.
func Assign(cur realm, id uint64, assignee address) {
	b := mustGet(id)
	before := b.Status
	check(b.Assign(cur.Previous().Address(), assignee, time.Now()))
	moved(b, before)
	index(assignee, id)
	emit("BountyAssigned", b, "assignee", assignee.String())
}

// Unassign returns an active bounty to the open pool. The assignee may step
// back at any time; the poster may reclaim it once the work window has
// passed. Milestones awaiting review or arbitration must be settled first.
func Unassign(cur realm, id uint64) {
	b := mustGet(id)
	before, prev := b.Status, b.Assignee
	check(b.Unassign(cur.Previous().Address(), time.Now()))
	moved(b, before)
	emit("BountyUnassigned", b, "previous", prev.String())
}

// Submit hands milestone (1-based) in for review, pointing at the work.
func Submit(cur realm, id uint64, milestone int, link string) {
	b := mustGet(id)
	check(b.Submit(cur.Previous().Address(), milestone-1, link, time.Now()))
	emit("MilestoneSubmitted", b, "milestone", strconv.Itoa(milestone), "link", link)
}

// Approve records a reviewer's approval of a submitted milestone. The
// approval that reaches the quorum releases the milestone's funds to the
// contributor and writes a reputation record.
func Approve(cur realm, id uint64, milestone int) {
	b := mustGet(id)
	caller := cur.Previous().Address()
	before := b.Status
	payouts, err := b.Approve(caller, milestone-1, time.Now())
	check(err)
	emit("MilestoneApproved", b, "milestone", strconv.Itoa(milestone), "reviewer", caller.String())
	m, _ := b.Milestone(milestone - 1)
	settle(0, cur, b, payouts, m.Approvals, false)
	moved(b, before)
}

// RequestChanges sends a submitted milestone back with feedback.
func RequestChanges(cur realm, id uint64, milestone int, feedback string) {
	b := mustGet(id)
	check(b.RequestChanges(cur.Previous().Address(), milestone-1, feedback))
	emit("MilestoneChangesRequested", b, "milestone", strconv.Itoa(milestone))
}

// OpenDispute escalates a submitted or rejected milestone to the arbiter.
// The poster or the contributor who submitted it may open one.
func OpenDispute(cur realm, id uint64, milestone int, reason string) {
	b := mustGet(id)
	caller := cur.Previous().Address()
	check(b.OpenDispute(caller, milestone-1, reason, time.Now()))
	emit("MilestoneDisputed", b, "milestone", strconv.Itoa(milestone), "by", caller.String())
}

// Resolve settles a disputed milestone. workerBps is the share, in basis
// points (0..10000), paid to the contributor; the rest is refunded to the
// poster. Arbiter only.
func Resolve(cur realm, id uint64, milestone int, workerBps int, ruling string) {
	b := mustGet(id)
	caller := cur.Previous().Address()
	if councilArbitrated.Has(idKey(id)) {
		// Council-arbitrated bounties follow the council's current owner.
		b.Arbiter = council.Owner()
	}
	before := b.Status
	payouts, err := b.Resolve(caller, milestone-1, int64(workerBps), ruling, time.Now())
	check(err)
	emit("DisputeResolved", b, "milestone", strconv.Itoa(milestone), "worker_bps", strconv.Itoa(workerBps))
	settle(0, cur, b, payouts, []address{caller}, true)
	moved(b, before)
}

// Cancel withdraws an open bounty and refunds every unpaid milestone to the
// poster. Active bounties must be unassigned first.
func Cancel(cur realm, id uint64) {
	b := mustGet(id)
	before := b.Status
	payouts, err := b.Cancel(cur.Previous().Address(), time.Now())
	check(err)
	settle(0, cur, b, payouts, nil, false)
	moved(b, before)
	emit("BountyCancelled", b)
}

// ---------------------------------------------------------------------------
// Council

// Council returns the default arbiter and operator of the board.
func Council() address {
	return council.Owner()
}

// TransferCouncil hands the council seat to a new address, typically an
// arbitration committee's multisig. Bounties posted with the council as
// arbiter follow. Only the current council can move the seat.
func TransferCouncil(cur realm, newCouncil address) {
	if err := council.TransferOwnership(0, cur, newCouncil); err != nil {
		panic(err.Error())
	}
	emitCouncil(newCouncil)
}

func emitCouncil(addr address) {
	chain.Emit("BountiesCouncilChanged", "council", addr.String())
}

// SetPaused stops (or resumes) the posting of new bounties. Work on existing
// bounties, payouts and refunds are never paused.
func SetPaused(cur realm, p bool) {
	council.AssertOwnedBy(cur.Previous().Address())
	paused = p
	chain.Emit("BountiesPaused", "paused", strconv.FormatBool(p))
}

// ---------------------------------------------------------------------------
// Queries

// Count returns the number of bounties ever posted.
func Count() int {
	return bounties.Size()
}

// CountByStatus returns the number of bounties in status ("open", "active",
// "completed" or "cancelled").
func CountByStatus(status string) int {
	s, ok := bounty.ParseStatus(status)
	if !ok {
		return 0
	}
	return statusCount[s]
}

// Escrowed returns what the board currently holds for denom (a native denom
// or a grc20reg key).
func Escrowed(denom string) int64 {
	v := escrowed.Get(denom)
	if v == nil {
		return 0
	}
	return v.(int64)
}

// IsPaused reports whether posting is paused.
func IsPaused() bool {
	return paused
}

// ---------------------------------------------------------------------------
// Internals

// settle executes payouts, crediting reputation for each payment to a worker.
func settle(_ int, rlm realm, b *bounty.Bounty, payouts []bounty.Payout, reviewers []address, arbitrated bool) {
	for _, p := range payouts {
		transfer(0, rlm, b, p.To, p.Amount)
		addEscrow(b, -p.Amount)
		m, _ := b.Milestone(p.Milestone)
		emit("Payout", b,
			"kind", string(p.Kind),
			"to", p.To.String(),
			"amount", strconv.FormatInt(p.Amount, 10),
			"milestone", strconv.Itoa(p.Milestone+1))
		if p.Kind != bounty.PayoutWork {
			continue
		}
		share := int64(bounty.MaxBps)
		if arbitrated && m.Amount > 0 {
			share = p.Amount * bounty.MaxBps / m.Amount
		}
		reputation.AddRecord(cross(rlm),
			p.To,
			b.Poster,
			reviewers,
			share,
			p.Amount,
			b.Denom,
			clip(b.Title+" — "+m.Title, 300),
			m.Submission,
			ufmt.Sprintf("%d/%d", b.ID, p.Milestone+1),
			arbitrated,
		)
	}
}

func transfer(_ int, rlm realm, b *bounty.Bounty, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if b.IsGRC20 {
		grc20reg.Transfer(0, rlm, b.Denom, to, amount)
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: b.Denom, Amount: amount}})
}

func mustGet(id uint64) *bounty.Bounty {
	v := bounties.Get(idKey(id))
	if v == nil {
		panic("bounties: unknown bounty " + strconv.FormatUint(id, 10))
	}
	return v.(*bounty.Bounty)
}

func getBounty(id uint64) *bounty.Bounty {
	v := bounties.Get(idKey(id))
	if v == nil {
		return nil
	}
	return v.(*bounty.Bounty)
}

func moved(b *bounty.Bounty, before bounty.Status) {
	if b.Status == before {
		return
	}
	statusCount[before]--
	statusCount[b.Status]++
}

func addEscrow(b *bounty.Bounty, delta int64) {
	cur := int64(0)
	if v := escrowed.Get(b.Denom); v != nil {
		cur = v.(int64)
	}
	escrowed.Set(b.Denom, cur+delta)
}

func index(addr address, id uint64) {
	if addr == "" {
		return
	}
	var t *avl.Tree
	if v := byUser.Get(addr.String()); v != nil {
		t = v.(*avl.Tree)
	} else {
		t = avl.NewTree()
		byUser.Set(addr.String(), t)
	}
	t.Set(idKey(id), struct{}{})
}

func assertNotPaused() {
	if paused {
		panic("bounties: posting is paused by the council")
	}
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

func emit(event string, b *bounty.Bounty, kv ...string) {
	attrs := append([]string{"id", strconv.FormatUint(b.ID, 10), "status", b.Status.String()}, kv...)
	chain.Emit(event, attrs...)
}

func idKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func clip(s string, n int) string {
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

package bounties

import (
	"chain"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounty/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	realmURL = "/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties"
	repURL   = "/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	pageSize = 20
)

// Render serves the bounty board:
//
//	""             the board (?status=open|active|completed|cancelled|all, ?tag=x, ?page=N)
//	<id>           a bounty with its milestones and next actions
//	u/<address>    bounties an address posted, works on, reviews or applied to
//	post           how to post a bounty
func Render(path string) string {
	route, query := splitQuery(path)
	parts := strings.Split(route, "/")
	switch {
	case parts[0] == "api":
		return renderAPI(route, query)
	case route == "":
		return renderBoard(query)
	case route == "post":
		return renderPost()
	case len(parts) == 2 && parts[0] == "u":
		return renderUser(address(parts[1]), pageOf(query))
	case len(parts) == 1:
		id, err := strconv.ParseUint(parts[0], 10, 64)
		if err != nil {
			return notFound()
		}
		return renderBounty(id)
	}
	return notFound()
}

func renderBoard(q url.Values) string {
	status := q.Get("status")
	if status == "" {
		status = "open"
	}
	tag := strings.ToLower(q.Get("tag"))
	page := pageOf(q)

	var b strings.Builder
	b.WriteString("# Guildhall Bounties\n\n")
	b.WriteString("Fund work, get it reviewed, pay on approval. Every payout becomes a public [reputation record](" + repURL + ").\n\n")
	b.WriteString(ufmt.Sprintf("**%d** open · **%d** in progress · **%d** completed · **%s** in escrow\n\n",
		statusCount[bounty.StatusOpen], statusCount[bounty.StatusActive], statusCount[bounty.StatusCompleted], escrowSummary()))
	if paused {
		b.WriteString("> Posting new bounties is paused by the council. Existing bounties are unaffected.\n\n")
	} else {
		b.WriteString("[+ Post a bounty](" + realmURL + ":post)\n\n")
	}

	var tabs []string
	for _, s := range []string{"open", "active", "completed", "cancelled", "all"} {
		label := s
		if s == status {
			label = "**" + s + "**"
		}
		link := realmURL + "?status=" + s
		if tag != "" {
			link += "&tag=" + url.QueryEscape(tag)
		}
		tabs = append(tabs, "["+label+"]("+link+")")
	}
	b.WriteString(strings.Join(tabs, " · "))
	if tag != "" {
		b.WriteString(" · tag: `" + sanitize.InlineText(tag) + "` ([clear](" + realmURL + "?status=" + url.QueryEscape(status) + "))")
	}
	b.WriteString("\n\n")

	want, filtered := bounty.ParseStatus(status)
	var matches []*bounty.Bounty
	skip := (page - 1) * pageSize
	more := false
	bounties.ReverseIterate("", "", func(_ string, v any) bool {
		bn := v.(*bounty.Bounty)
		if filtered && bn.Status != want {
			return false
		}
		if tag != "" && !hasTag(bn, tag) {
			return false
		}
		if skip > 0 {
			skip--
			return false
		}
		if len(matches) == pageSize {
			more = true
			return true
		}
		matches = append(matches, bn)
		return false
	})
	b.WriteString(bountyTable(matches))

	var nav []string
	if page > 1 {
		nav = append(nav, "[← newer]("+boardLink(status, tag, page-1)+")")
	}
	if more {
		nav = append(nav, "[older →]("+boardLink(status, tag, page+1)+")")
	}
	if len(nav) > 0 {
		b.WriteString("\n" + strings.Join(nav, " · ") + "\n")
	}
	return b.String()
}

func renderBounty(id uint64) string {
	bn := getBounty(id)
	if bn == nil {
		return notFound()
	}
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# #%d %s\n\n", bn.ID, sanitize.InlineText(bn.Title)))
	b.WriteString(ufmt.Sprintf("**%s** · %s · posted %s", strings.ToUpper(bn.Status.String()), formatAmount(bn, bn.Total()), bn.CreatedAt.UTC().Format("2006-01-02")))
	if len(bn.Tags) > 0 {
		var ts []string
		for _, t := range bn.Tags {
			ts = append(ts, "["+t+"]("+realmURL+"?status=all&tag="+url.QueryEscape(t)+")")
		}
		b.WriteString(" · " + strings.Join(ts, " "))
	}
	b.WriteString("\n\n")

	if bn.Description != "" {
		b.WriteString(sanitize.Block(bn.Description) + "\n\n")
	}
	if bn.Link != "" {
		b.WriteString("Reference: " + linkOrText(bn.Link) + "\n\n")
	}

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Posted by | " + person(bn.Poster) + " |\n")
	if bn.Assignee != "" {
		b.WriteString("| Assigned to | " + person(bn.Assignee) + " since " + bn.AssignedAt.UTC().Format("2006-01-02") + " |\n")
	}
	var revs []string
	for _, r := range bn.Reviewers {
		revs = append(revs, person(r))
	}
	b.WriteString(ufmt.Sprintf("| Reviewers (%d of %d must approve) | %s |\n", bn.Quorum, len(bn.Reviewers), strings.Join(revs, ", ")))
	arb := person(bn.Arbiter)
	if councilArbitrated.Has(idKey(bn.ID)) {
		arb = "Guildhall council (" + person(council.Owner()) + ")"
	}
	b.WriteString("| Arbiter | " + arb + " |\n")
	b.WriteString(ufmt.Sprintf("| Work window | %d days |\n", int(bn.WorkWindow.Hours()/24)))
	b.WriteString("| Escrow | " + formatAmount(bn, bn.Escrowed()) + " held · " + formatAmount(bn, bn.PaidOut()) + " paid |\n\n")

	b.WriteString("## Milestones\n\n")
	b.WriteString("| # | Milestone | Reward | Status | Work | Approvals |\n|---:|---|---:|---|---|---|\n")
	for i, m := range bn.Milestones {
		work := "-"
		if m.Submission != "" {
			work = linkOrText(m.Submission)
		}
		b.WriteString(ufmt.Sprintf("| %d | %s | %s | %s | %s | %d/%d |\n",
			i+1, sanitize.TableCell(m.Title), formatAmount(bn, m.Amount), milestoneStatus(m), work, len(m.Approvals), bn.Quorum))
	}
	b.WriteString("\n")

	for i, m := range bn.Milestones {
		if m.Feedback != "" && m.Status == bounty.MilestoneChangesRequested {
			b.WriteString(ufmt.Sprintf("> **Milestone %d, changes requested:** %s\n\n", i+1, sanitize.InlineText(m.Feedback)))
		}
		if d := m.Dispute; d != nil {
			b.WriteString(ufmt.Sprintf("> **Milestone %d, disputed by %s:** %s\n", i+1, person(d.OpenedBy), sanitize.InlineText(d.Reason)))
			if d.Resolved {
				ruling := ""
				if d.Ruling != "" {
					ruling = ": " + sanitize.InlineText(d.Ruling)
				}
				b.WriteString(ufmt.Sprintf(">\n> **Ruling:** %s to the worker%s\n", bps(d.WorkerBps), ruling))
			}
			b.WriteString("\n")
		}
	}

	b.WriteString(renderActions(bn))

	if bn.Status == bounty.StatusOpen && len(bn.Applications) > 0 {
		b.WriteString("## Applications\n\n| Applicant | Reputation | Pitch | |\n|---|---:|---|---|\n")
		for _, a := range bn.Applications {
			assign := txlink.NewLink("Assign").AddArgs("id", idStr(bn), "assignee", a.Applicant.String()).URL()
			b.WriteString(ufmt.Sprintf("| %s | %d | %s | [assign](%s) |\n",
				person(a.Applicant), reputation.Score(a.Applicant), sanitize.TableCell(a.Pitch), assign))
		}
		b.WriteString("\n")
	}
	return b.String()
}

// renderActions lists the transactions that can move the bounty forward, as
// gnoweb transaction links. The chain enforces who may call them; the page
// just lists them all.
func renderActions(bn *bounty.Bounty) string {
	var acts []string
	id := idStr(bn)
	add := func(label, fn string, args ...string) {
		acts = append(acts, "["+label+"]("+txlink.NewLink(fn).AddArgs(append([]string{"id", id}, args...)...).URL()+")")
	}

	switch bn.Status {
	case bounty.StatusOpen:
		add("Apply", "Apply")
		add("Assign (poster)", "Assign")
		add("Cancel and refund (poster)", "Cancel")
	case bounty.StatusActive:
		for i, m := range bn.Milestones {
			n := strconv.Itoa(i + 1)
			switch m.Status {
			case bounty.MilestonePending, bounty.MilestoneChangesRequested:
				add("Submit milestone "+n+" (assignee)", "Submit", "milestone", n)
				if m.Status == bounty.MilestoneChangesRequested {
					add("Dispute milestone "+n, "OpenDispute", "milestone", n)
				}
			case bounty.MilestoneSubmitted:
				add("Approve milestone "+n+" (reviewer)", "Approve", "milestone", n)
				add("Request changes on "+n+" (reviewer)", "RequestChanges", "milestone", n)
				add("Dispute milestone "+n, "OpenDispute", "milestone", n)
			case bounty.MilestoneDisputed:
				add("Resolve milestone "+n+" (arbiter)", "Resolve", "milestone", n)
			}
		}
		add("Step back / reclaim", "Unassign")
	}
	if len(acts) == 0 {
		return ""
	}
	return "## Actions\n\n" + strings.Join(acts, " · ") + "\n\n"
}

func renderUser(addr address, page int) string {
	if !addr.IsValid() {
		return notFound()
	}
	var b strings.Builder
	b.WriteString("# Bounties for " + addr.String() + "\n\n")
	b.WriteString(ufmt.Sprintf("Reputation: **%d** (%s) · [profile](%s:u/%s)\n\n",
		reputation.Score(addr), reputation.Level(addr), repURL, addr.String()))
	v := byUser.Get(addr.String())
	if v == nil {
		b.WriteString("_Not involved in any bounty yet._\n")
		return b.String()
	}
	ids := v.(*avl.Tree)
	var list []*bounty.Bounty
	ids.ReverseIterateByOffset((page-1)*pageSize, pageSize, func(k string, _ any) bool {
		if bv := bounties.Get(k); bv != nil {
			list = append(list, bv.(*bounty.Bounty))
		}
		return false
	})
	b.WriteString("| # | Bounty | Role | Reward | Status |\n|---:|---|---|---:|---|\n")
	for _, bn := range list {
		b.WriteString(ufmt.Sprintf("| %d | [%s](%s:%d) | %s | %s | %s |\n",
			bn.ID, sanitize.TableCell(bn.Title), realmURL, bn.ID, role(bn, addr), formatAmount(bn, bn.Total()), bn.Status.String()))
	}
	if ids.Size() > page*pageSize {
		b.WriteString(ufmt.Sprintf("\n[older →](%s:u/%s?page=%d)\n", realmURL, addr.String(), page+1))
	}
	return b.String()
}

func renderPost() string {
	native := txlink.NewLink("PostBounty").
		AddArgs("title", "", "description", "", "link", "", "tags", "", "reviewers", "", "quorum", "1", "milestones", "", "arbiter", "", "workWindowDays", "30").
		SetSend("1000000ugnot").URL()
	grc := txlink.NewLink("PostBountyGRC20").
		AddArgs("tokenKey", "", "title", "", "milestones", "", "quorum", "1", "workWindowDays", "30").URL()

	var b strings.Builder
	b.WriteString("# Post a bounty\n\n")
	b.WriteString("## With GNOT\n\n")
	b.WriteString("[Open the form](" + native + ") and set the amount to send to the bounty's total.\n\n")
	b.WriteString("- **milestones**: `Title=amount;Title=amount` in the smallest unit (`ugnot`). They must add up to exactly what you send. Leave empty for a single milestone worth everything sent.\n")
	b.WriteString("- **reviewers**: comma-separated addresses. Leave empty to review it yourself.\n")
	b.WriteString("- **quorum**: how many reviewers must approve each milestone.\n")
	b.WriteString("- **arbiter**: who settles disputes. Leave empty for the Guildhall council.\n")
	b.WriteString("- **workWindowDays**: after this many days without progress you can take the bounty back from its assignee (default 30).\n\n")
	b.WriteString("```sh\ngnokey maketx call -pkgpath gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties -func PostBounty \\\n")
	b.WriteString("  -args \"Port faucet to interrealm v2\" -args \"Rewrite r/faucet using cur realm\" \\\n")
	b.WriteString("  -args \"https://github.com/gnolang/gno/issues/1234\" -args \"realm,good-first-issue\" \\\n")
	b.WriteString("  -args \"g1reviewer1...,g1reviewer2...\" -args 2 \\\n")
	b.WriteString("  -args \"Design=20000000;Implementation=80000000\" -args \"\" -args 30 \\\n")
	b.WriteString("  -send 100000000ugnot -gas-fee 1000000ugnot -gas-wanted 20000000 -broadcast -chainid gnoland1 KEY\n```\n\n")
	b.WriteString("## With a GRC20 token\n\n")
	b.WriteString("1. Approve `" + chain.PackageAddress("gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties").String() + "` on the token for the bounty's total.\n")
	b.WriteString("2. Call [PostBountyGRC20](" + grc + ") with the token's [grc20reg](/r/nt/grc20reg/v0) key. Milestone amounts are required.\n")
	return b.String()
}

func bountyTable(list []*bounty.Bounty) string {
	if len(list) == 0 {
		return "_No bounties here yet._\n"
	}
	var b strings.Builder
	b.WriteString("| # | Bounty | Reward | Progress | Status | Poster |\n|---:|---|---:|---|---|---|\n")
	for _, bn := range list {
		settled := 0
		for _, m := range bn.Milestones {
			if m.Status.Settled() {
				settled++
			}
		}
		b.WriteString(ufmt.Sprintf("| %d | [%s](%s:%d)%s | %s | %d/%d | %s | %s |\n",
			bn.ID, sanitize.TableCell(bn.Title), realmURL, bn.ID, tagSuffix(bn), formatAmount(bn, bn.Total()),
			settled, len(bn.Milestones), bn.Status.String(), person(bn.Poster)))
	}
	return b.String()
}

func milestoneStatus(m *bounty.Milestone) string {
	switch m.Status {
	case bounty.MilestonePaid:
		return "✅ paid"
	case bounty.MilestoneSplit:
		return "⚖️ split"
	case bounty.MilestoneRefunded:
		return "↩️ refunded"
	case bounty.MilestoneDisputed:
		return "⚠️ disputed"
	case bounty.MilestoneSubmitted:
		return "🔍 in review"
	case bounty.MilestoneChangesRequested:
		return "✏️ changes requested"
	}
	return "⏳ pending"
}

func role(bn *bounty.Bounty, addr address) string {
	if rs := roles(bn, addr); len(rs) > 0 {
		return strings.Join(rs, ", ")
	}
	return "-"
}

func hasTag(bn *bounty.Bounty, tag string) bool {
	for _, t := range bn.Tags {
		if t == tag {
			return true
		}
	}
	return false
}

func tagSuffix(bn *bounty.Bounty) string {
	if len(bn.Tags) == 0 {
		return ""
	}
	return " `" + strings.Join(bn.Tags, "` `") + "`"
}

func person(addr address) string {
	if addr == "" {
		return "-"
	}
	s := addr.String()
	short := s
	if len(s) > 14 {
		short = s[:8] + "…" + s[len(s)-4:]
	}
	return "[" + short + "](" + repURL + ":u/" + s + ")"
}

func linkOrText(s string) string {
	if u := sanitize.URL(s); u != "" && (strings.HasPrefix(s, "https://") || strings.HasPrefix(s, "/")) {
		return "[" + sanitize.LinkTitle(s) + "](" + u + ")"
	}
	return sanitize.InlineText(s)
}

func formatAmount(bn *bounty.Bounty, amount int64) string {
	if bn.IsGRC20 {
		if tok := grc20reg.Get(bn.Denom); tok != nil {
			return decimal(amount, tok.GetDecimals()) + " " + sanitize.InlineText(tok.GetSymbol())
		}
		return strconv.FormatInt(amount, 10) + " " + sanitize.InlineText(bn.Denom)
	}
	if bn.Denom == "ugnot" {
		return decimal(amount, 6) + " GNOT"
	}
	return strconv.FormatInt(amount, 10) + " " + sanitize.InlineText(bn.Denom)
}

func escrowSummary() string {
	var parts []string
	escrowed.Iterate("", "", func(k string, v any) bool {
		amt := v.(int64)
		if amt <= 0 {
			return false
		}
		switch {
		case k == "ugnot":
			parts = append(parts, decimal(amt, 6)+" GNOT")
		case grc20reg.Get(k) != nil:
			tok := grc20reg.Get(k)
			parts = append(parts, decimal(amt, tok.GetDecimals())+" "+sanitize.InlineText(tok.GetSymbol()))
		default:
			parts = append(parts, strconv.FormatInt(amt, 10)+" "+sanitize.InlineText(k))
		}
		return false
	})
	if len(parts) == 0 {
		return "nothing"
	}
	return strings.Join(parts, " + ")
}

func decimal(amount int64, decimals int) string {
	if decimals <= 0 {
		return strconv.FormatInt(amount, 10)
	}
	s := strconv.FormatInt(amount, 10)
	neg := strings.HasPrefix(s, "-")
	s = strings.TrimPrefix(s, "-")
	for len(s) <= decimals {
		s = "0" + s
	}
	whole, frac := s[:len(s)-decimals], strings.TrimRight(s[len(s)-decimals:], "0")
	if neg {
		whole = "-" + whole
	}
	if frac == "" {
		return whole
	}
	return whole + "." + frac
}

func bps(v int64) string {
	return decimal(v, 2) + "%"
}

func idStr(bn *bounty.Bounty) string {
	return strconv.FormatUint(bn.ID, 10)
}

func boardLink(status, tag string, page int) string {
	l := realmURL + "?status=" + url.QueryEscape(status) + "&page=" + strconv.Itoa(page)
	if tag != "" {
		l += "&tag=" + url.QueryEscape(tag)
	}
	return l
}

func splitQuery(path string) (string, url.Values) {
	route, raw := path, ""
	if i := strings.Index(path, "?"); i >= 0 {
		route, raw = path[:i], path[i+1:]
	}
	q, _ := url.ParseQuery(raw)
	return strings.Trim(route, "/"), q
}

func pageOf(q url.Values) int {
	p, err := strconv.Atoi(q.Get("page"))
	if err != nil || p < 1 {
		return 1
	}
	return p
}

func notFound() string {
	return "# Not found\n\n[Back to the board](" + realmURL + ")\n"
}

// Package govdao is an optional, one-way adapter from Guildhall reputation to
// GovDAO membership. Guildhall does not depend on it and GovDAO has no
// authority over it or over any other Guildhall realm; it only reads
// reputation and builds proposals that GovDAO members may choose to submit.
//
// It turns a contributor's on-chain work records into two inputs for GovDAO:
//
//   - an eligibility check: a minimum reputation score per tier, and
//   - a portfolio: a summary of the contributor's paid, reviewed work, with
//     links to every record, generated from chain state rather than written
//     by hand.
//
// GovDAO only accepts proposals created directly by a member's transaction,
// so this realm never creates proposals itself. It builds the request; the
// member submits it from a `gnokey maketx run` script:
//
//	package main
//
//	import (
//		"gno.land/r/gov/dao"
//		guild "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/govdao"
//	)
//
//	func main(cur realm) {
//		req := guild.NewMemberRequest(cross(cur), "g1candidate...", "T2")
//		dao.MustCreateProposal(cross(cur), req)
//	}
//
// The thresholds are set by the Guildhall admin with SetThreshold. They are
// Guildhall's bar for the candidates it vouches for; GovDAO's vote decides.
package govdao

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/jsonw/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
	"gno.land/r/gov/dao"
	impl "gno.land/r/gov/dao/impl/v0"
	"gno.land/r/gov/dao/memberstore/v0"
)

const (
	portfolioRecords = 10
	chainURL         = "https://gno.land"
)

// thresholds maps tier -> minimum reputation score.
var thresholds avl.Tree

func init() {
	thresholds.Set(memberstore.T1, int64(2000))
	thresholds.Set(memberstore.T2, int64(800))
	thresholds.Set(memberstore.T3, int64(300))
}

// Threshold returns the minimum score required to be proposed for tier.
func Threshold(tier string) int64 {
	v := thresholds.Get(tier)
	if v == nil {
		return -1
	}
	return v.(int64)
}

// Eligible reports whether addr meets the reputation bar for tier and, if
// not, why.
func Eligible(addr address, tier string) (bool, string) {
	min := Threshold(tier)
	if min < 0 {
		return false, "unknown tier " + strconv.Quote(tier)
	}
	if !addr.IsValid() {
		return false, "invalid address"
	}
	score := reputation.Score(addr)
	if score < min {
		return false, ufmt.Sprintf("reputation %d is below the %s threshold of %d", score, tier, min)
	}
	return true, ""
}

// AssertEligible panics unless addr meets the reputation bar for tier.
func AssertEligible(addr address, tier string) {
	if ok, why := Eligible(addr, tier); !ok {
		panic("guildhall: " + why)
	}
}

// Portfolio renders addr's Guildhall track record as markdown suitable for a
// GovDAO membership proposal.
func Portfolio(addr address) string {
	var b strings.Builder
	score := reputation.Score(addr)
	b.WriteString(ufmt.Sprintf("**Guildhall reputation: %d (%s)**", score, reputation.Level(addr)))
	if r := reputation.Rank(addr); r > 0 {
		b.WriteString(ufmt.Sprintf(", ranked #%d", r))
	}
	b.WriteString("\n\n")
	b.WriteString(ufmt.Sprintf("- Paid work records: %d\n", reputation.CompletedCount(addr)))
	b.WriteString(ufmt.Sprintf("- Reviews given: %d\n", reputation.ReviewCount(addr)))
	if gnot := reputation.Earned(addr, "ugnot"); gnot > 0 {
		b.WriteString("- Earned through bounties: " + gnotString(gnot) + "\n")
	}
	b.WriteString(ufmt.Sprintf("- Full profile: %s/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation:u/%s\n\n", chainURL, addr.String()))

	recs := reputation.RecordsOf(addr, 0, portfolioRecords)
	if len(recs) > 0 {
		b.WriteString("Most recent work:\n\n")
		for _, r := range recs {
			if r.Voided {
				continue
			}
			b.WriteString(ufmt.Sprintf("- %s (+%d, record #%d)", sanitize.InlineText(r.Title), r.Points, r.ID))
			if u := sanitize.URL(r.Link); u != "" && strings.HasPrefix(r.Link, "https://") {
				b.WriteString(" · [work](" + u + ")")
			}
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("_Generated from on-chain records by gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/govdao._")
	return b.String()
}

// NewMemberRequest builds a GovDAO proposal to add addr to tier, with its
// Guildhall portfolio attached. It panics if addr does not meet the tier's
// reputation threshold. GovDAO's own rules still apply: the signer must be a
// member with an invitation point, and only T1 and T2 are proposal-gated.
func NewMemberRequest(cur realm, addr address, tier string) dao.ProposalRequest {
	AssertEligible(addr, tier)
	return impl.NewAddMemberRequest(cross(cur), addr, tier, Portfolio(addr))
}

// SetThreshold changes the minimum score for tier. Only the Guildhall admin
// (reputation.Admin) may call it: the bar is Guildhall's statement of who it
// vouches for, and GovDAO is free to ignore it.
func SetThreshold(cur realm, tier string, min int64) {
	if cur.Previous().Address() != reputation.Admin() {
		panic("guildhall: only the Guildhall admin may change thresholds")
	}
	validateThreshold(tier, min)
	thresholds.Set(tier, min)
	chain.Emit("GuildhallThresholdChanged", "tier", tier, "min", strconv.FormatInt(min, 10))
}

func validateThreshold(tier string, min int64) {
	if _, ok := memberstore.GetTier(tier); !ok {
		panic("guildhall: unknown tier " + strconv.Quote(tier))
	}
	if min < 0 {
		panic("guildhall: threshold must not be negative")
	}
}

// Render shows the thresholds and, for u/<address>, that address's
// eligibility and generated portfolio.
func Render(path string) string {
	path = strings.Trim(path, "/")
	if strings.HasPrefix(path, "api/candidate/") {
		return apiCandidate(address(strings.TrimPrefix(path, "api/candidate/")))
	}
	if strings.HasPrefix(path, "u/") {
		return renderCandidate(address(strings.TrimPrefix(path, "u/")))
	}
	var b strings.Builder
	b.WriteString("# Guildhall × GovDAO\n\n")
	b.WriteString("Guildhall reputation is an on-chain input to GovDAO membership. A contributor can be proposed for a tier once their score reaches its threshold, and the proposal carries a portfolio generated from their work records.\n\n")
	b.WriteString("| Tier | Minimum reputation |\n|---|---:|\n")
	thresholds.Iterate("", "", func(k string, v any) bool {
		b.WriteString(ufmt.Sprintf("| %s | %d |\n", k, v.(int64)))
		return false
	})
	b.WriteString("\nThresholds are set by the Guildhall admin. GovDAO's vote still decides every membership; Guildhall only vouches.\n\n")
	b.WriteString("Check a candidate at `/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/govdao:u/<address>`.\n\n")
	b.WriteString("## Proposing a member\n\n```go\npackage main\n\nimport (\n\t\"gno.land/r/gov/dao\"\n\tguild \"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/govdao\"\n)\n\nfunc main(cur realm) {\n\treq := guild.NewMemberRequest(cross(cur), \"g1candidate...\", \"T2\")\n\tdao.MustCreateProposal(cross(cur), req)\n}\n```\n\n")
	b.WriteString("Run it with `gnokey maketx run` from a GovDAO member's key.\n")
	return b.String()
}

func renderCandidate(addr address) string {
	if !addr.IsValid() {
		return "# Not found\n"
	}
	var b strings.Builder
	b.WriteString("# Candidate " + addr.String() + "\n\n")
	b.WriteString("| Tier | Required | Eligible |\n|---|---:|---|\n")
	thresholds.Iterate("", "", func(k string, v any) bool {
		mark := "no"
		if ok, _ := Eligible(addr, k); ok {
			mark = "yes"
		}
		b.WriteString(ufmt.Sprintf("| %s | %d | %s |\n", k, v.(int64), mark))
		return false
	})
	b.WriteString("\n## Portfolio\n\n" + Portfolio(addr) + "\n")
	return b.String()
}

// apiCandidate serves JSON for the web app: per-tier thresholds and whether
// addr meets each.
func apiCandidate(addr address) string {
	if !addr.IsValid() {
		return jsonw.Obj("error", jsonw.String("invalid address"))
	}
	var tiers []string
	thresholds.Iterate("", "", func(k string, v any) bool {
		ok, _ := Eligible(addr, k)
		tiers = append(tiers, jsonw.Obj("tier", jsonw.String(k), "min", jsonw.Int(v.(int64)), "eligible", jsonw.Bool(ok)))
		return false
	})
	return jsonw.Obj("address", jsonw.String(addr.String()), "score", jsonw.Int(reputation.Score(addr)), "tiers", jsonw.Arr(tiers))
}

func gnotString(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fs := strconv.FormatInt(frac, 10)
	for len(fs) < 6 {
		fs = "0" + fs
	}
	return strconv.FormatInt(whole, 10) + "." + strings.TrimRight(fs, "0") + " GNOT"
}

// Package guildhall is the front door of Guildhall: fund work, track it, and
// turn finished work into a record anyone can check.
//
//	gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties     escrowed bounties with milestones, reviewers and disputes
//	gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation   work records and reputation other realms can import
//	gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/govdao       optional adapter: reputation as an input to GovDAO membership
package guildhall

import (
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/trust/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation"
)

func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# Guildhall\n\n")
	b.WriteString("**Fund work, track it, and turn finished work into a record anyone can check.**\n\n")
	b.WriteString("Post a task and escrow GNOT or any registered GRC20 token against it. Split it into milestones and name the reviewers. ")
	b.WriteString("Each approved milestone pays the contributor and writes a public record of the work: who did it, who vouched for it, and a link to the PR, realm or proposal. ")
	b.WriteString("Those records add up to a reputation that any realm can read with one import. Guildhall governs itself; no outside realm has authority over it.\n\n")

	b.WriteString(ufmt.Sprintf("| Open bounties | In progress | Completed | Work records | Ranked contributors |\n|---:|---:|---:|---:|---:|\n| %d | %d | %d | %d | %d |\n\n",
		bounties.CountByStatus("open"), bounties.CountByStatus("active"), bounties.CountByStatus("completed"),
		reputation.RecordCount(), reputation.ContributorCount()))

	b.WriteString("- [**Bounty board**](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties): find work or [post a bounty](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/bounties:post)\n")
	b.WriteString("- [**Reputation**](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation): leaderboard, profiles and [how scoring works](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation:about)\n")
	b.WriteString("- [**GovDAO**](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/govdao): an optional bridge that lets GovDAO members propose high-reputation contributors\n\n")

	top := reputation.Top(5)
	if len(top) > 0 {
		b.WriteString("## Top contributors\n\n")
		for i, s := range top {
			b.WriteString(ufmt.Sprintf("%d. [%s](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation:u/%s): %d (%s)\n", i+1, s.Addr.String(), s.Addr.String(), s.Score, trust.Level(s.Score)))
		}
		b.WriteString("\n")
	}

	b.WriteString("## How it works\n\n")
	b.WriteString("1. **Post.** Send funds with `PostBounty`. They stay in the realm, not with the poster.\n")
	b.WriteString("2. **Assign.** Contributors apply and the poster picks one.\n")
	b.WriteString("3. **Deliver.** The contributor submits each milestone with a link to the work.\n")
	b.WriteString("4. **Review.** Once enough reviewers approve, the milestone pays out and a reputation record is written.\n")
	b.WriteString("5. **Dispute.** If reviewer and contributor disagree, the arbiter pays, refunds or splits.\n\n")

	b.WriteString("## Gate your realm on reputation\n\n")
	b.WriteString("```go\nimport \"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/guildhall/reputation\"\n\nfunc Post(cur realm, body string) {\n\treputation.AssertScore(cur.Previous().Address(), 100)\n\t// ...\n}\n```\n")
	return b.String()
}

package connect4_v4

// The chain decodes four texts to the same address: the bech32 form it gives
// a caller, that form in capitals, and the bech32m checksum in either case.
// An address argument stored as text and later compared with a caller's
// address must be that first form. canonical reads the text itself, which
// costs far less gas than decoding and re-encoding it. It is the check of
// gno.land/p/samcrew/launchpad/meta/v1 (ValidAddress), copied so this realm
// does not depend on that package being published.

// bech32Value holds, for each character of the bech32 alphabet
// "qpzry9x8gf2tvdw0s3jn54khce6mua7l", its 5-bit value plus one. Zero marks
// every other byte, capitals included.
var bech32Value = [256]byte{
	'q': 1, 'p': 2, 'z': 3, 'r': 4, 'y': 5, '9': 6, 'x': 7, '8': 8,
	'g': 9, 'f': 10, '2': 11, 't': 12, 'v': 13, 'd': 14, 'w': 15, '0': 16,
	's': 17, '3': 18, 'j': 19, 'n': 20, '5': 21, '4': 22, 'k': 23, 'h': 24,
	'c': 25, 'e': 26, '6': 27, 'm': 28, 'u': 29, 'a': 30, '7': 31, 'l': 32,
}

// bech32Gen[t] is the XOR of the BIP-173 generators selected by the five
// bits of t: one table read per character instead of five tests.
var bech32Gen = [32]uint32{
	0x00000000, 0x3b6a57b2, 0x26508e6d, 0x1d3ad9df,
	0x1ea119fa, 0x25cb4e48, 0x38f19797, 0x039bc025,
	0x3d4233dd, 0x0628646f, 0x1b12bdb0, 0x2078ea02,
	0x23e32a27, 0x18897d95, 0x05b3a44a, 0x3ed9f3f8,
	0x2a1462b3, 0x117e3501, 0x0c44ecde, 0x372ebb6c,
	0x34b57b49, 0x0fdf2cfb, 0x12e5f524, 0x298fa296,
	0x1756516e, 0x2c3c06dc, 0x3106df03, 0x0a6c88b1,
	0x09f74894, 0x329d1f26, 0x2fa7c6f9, 0x14cd914b,
}

// The checksum state once the address prefix "g" has been absorbed, which
// BIP-173 expands to the values 3, 0, 7.
const bech32PrefixState uint32 = 0x8c07

// canonical reports whether a is "g1", then 38 lowercase bech32 characters
// whose checksum is the original bech32 one: the form a caller's address has.
func canonical(a address) bool {
	s := string(a)
	if len(s) != 40 || s[0] != 'g' || s[1] != '1' {
		return false
	}
	chk := bech32PrefixState
	for i := 2; i < 40; i++ {
		v := bech32Value[s[i]]
		if v == 0 {
			return false
		}
		chk = (chk&0x1ffffff)<<5 ^ uint32(v-1) ^ bech32Gen[chk>>25]
	}
	return chk == 1 // 1 is bech32; bech32m ends on 0x2bc830a3
}

package connect4_v4

const (
	cols = 7
	rows = 6
)

// board is indexed [column][row]; row 0 is the bottom. 0 = empty, 1/2 = player.
type board [cols][rows]byte

// drop places piece p in column c (0-based) and returns its row, or -1 if the column is full.
func (b *board) drop(c int, p byte) int {
	for r := 0; r < rows; r++ {
		if b[c][r] == 0 {
			b[c][r] = p
			return r
		}
	}
	return -1
}

// wins reports whether the piece at (c, r) is part of four in a row.
func (b *board) wins(c, r int) bool { return b.winLine(c, r) != nil }

// winLine returns the cells of the four-or-more line through (c, r), in order
// along the line, or nil if the piece there completes none.
func (b *board) winLine(c, r int) [][2]int {
	p := b[c][r]
	for _, d := range [4][2]int{{1, 0}, {0, 1}, {1, 1}, {1, -1}} {
		back := b.count(c, r, -d[0], -d[1], p)
		n := 1 + back + b.count(c, r, d[0], d[1], p)
		if n >= 4 {
			line := make([][2]int, n)
			for i := range line {
				k := i - back
				line[i] = [2]int{c + k*d[0], r + k*d[1]}
			}
			return line
		}
	}
	return nil
}

// count returns how many consecutive p pieces follow (c, r) in direction (dc, dr).
func (b *board) count(c, r, dc, dr int, p byte) int {
	n := 0
	for {
		c, r = c+dc, r+dr
		if c < 0 || c >= cols || r < 0 || r >= rows || b[c][r] != p {
			return n
		}
		n++
	}
}

package connect4_v4

import "testing"

func play(b *board, p byte, colsPlayed ...int) (int, int) {
	c, r := 0, 0
	for _, c = range colsPlayed {
		r = b.drop(c, p)
	}
	return c, r
}

func TestWins(t *testing.T) {
	cases := []struct {
		name  string
		setup func(b *board) (int, int)
		want  bool
	}{
		{"horizontal", func(b *board) (int, int) { return play(b, 1, 0, 1, 2, 3) }, true},
		{"vertical", func(b *board) (int, int) { return play(b, 1, 4, 4, 4, 4) }, true},
		{"three only", func(b *board) (int, int) { return play(b, 1, 0, 1, 2) }, false},
		{"diagonal up", func(b *board) (int, int) {
			play(b, 2, 1, 2, 2, 3, 3, 3)
			return play(b, 1, 0, 1, 2, 3)
		}, true},
		{"diagonal down", func(b *board) (int, int) {
			play(b, 2, 3, 3, 3, 2, 2, 1)
			return play(b, 1, 3, 2, 1, 0)
		}, true},
		{"gap breaks line", func(b *board) (int, int) { return play(b, 1, 0, 1, 3, 4) }, false},
	}
	for _, tc := range cases {
		var b board
		c, r := tc.setup(&b)
		if got := b.wins(c, r); got != tc.want {
			t.Errorf("%s: wins=%v, want %v", tc.name, got, tc.want)
		}
	}
}

func TestDropFullColumn(t *testing.T) {
	var b board
	for i := 0; i < rows; i++ {
		if b.drop(0, 1) != i {
			t.Fatalf("drop %d landed on wrong row", i)
		}
	}
	if b.drop(0, 1) != -1 {
		t.Fatal("drop into full column should return -1")
	}
}

func TestWinLine(t *testing.T) {
	var b board
	if c, r := play(&b, 1, 0, 1, 2); b.winLine(c, r) != nil {
		t.Fatal("three in a row is not a win")
	}
	c, r := play(&b, 1, 3)
	line := b.winLine(c, r)
	if len(line) != 4 {
		t.Fatalf("want 4 winning cells, got %v", line)
	}
	for i, cell := range line {
		if cell != [2]int{i, 0} {
			t.Fatalf("cell %d = %v, want [%d 0]", i, cell, i)
		}
	}
}

// package connect4_v4 is a staked Connect 4 game. A creator posts an offer with
// a ugnot stake; anyone (or a named opponent) accepts with the same stake;
// the winner takes the pot minus a flat house fee.
//
// The first mover is picked by a two-sided commit-reveal. The creator offers
// with sha256(passphrase), the acceptor accepts with sha256(seed). Then the
// creator reveals the passphrase (Reveal) and the acceptor the seed
// (RevealSeed), each within 90s, and the first mover is drawn from both. When
// a player commits, the other side's secret is still hidden, so neither can
// grind for an outcome, and once its secret is revealed nobody can change it;
// the only way out is to not reveal, which forfeits. Watching a pending Accept
// tells the creator nothing either, so it cannot cancel unfavourable games.
// Each address may use a commitment once: a reused secret is already public.
//
// Calls signed by an account session key (Quick play) may only Play, Reveal,
// RevealSeed, ClaimTimeout and Cancel: a stolen session key must not resign
// games, move stakes or act as the owner.
//
// Every move has a 90s clock measured in block time. Nothing on-chain fires
// by itself, so an expired clock is settled by anyone calling ClaimTimeout:
// whoever did not reveal in time forfeits, a game whose first mover never
// moved is void and both stakes are refunded, otherwise the player who ran
// out of time forfeits.
package connect4_v4

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	moveTimeout = 90 * time.Second
	maxOfferTTL = 60 // minutes
	feeCap      = minStake / 2
	minStake    = 1_000_000 // ugnot
	denom       = "ugnot"
)

type Status int

const (
	Open Status = iota
	Playing
	Won
	Draw
	Void
	Cancelled
)

func (s Status) String() string {
	return [...]string{"open", "playing", "won", "draw", "void", "cancelled"}[s]
}

type Game struct {
	ID        int
	Creator   address
	Opponent  address // optional; if set, only this address may accept
	Acceptor  address
	Stake     int64 // ugnot, per player
	Fee       int64 // ugnot house fee, fixed at offer time
	ExpiresAt time.Time
	// Commitment is the lowercase hex sha256 of the creator's passphrase;
	// SeedCommitment that of the acceptor's seed, given with Accept.
	Commitment     string
	SeedCommitment string
	// Passphrase is set by Reveal; the draw waits for RevealSeed.
	Passphrase string
	Revealed   bool

	Board    board
	Turn     byte // 0 = awaiting the reveals, 1 = creator, 2 = acceptor
	Moves    int
	LastCol  int // column and row of the last piece dropped, valid if Moves > 0
	LastRow  int
	LastMove time.Time
	Status   Status
	Winner   address
}

type Stats struct {
	Games, Wins, Draws int
	GnotWon            int64 // total net ugnot won: the opponent's stake minus the fee
}

var (
	games         avl.Tree // key(id) -> *Game
	active        avl.Tree // key(id) -> *Game, only Open and Playing
	stats         avl.Tree // address -> *Stats
	nextID        int
	fee           int64 = 100_000 // ugnot per decisive game
	feesCollected int64
	owner         *ownable.Ownable // the deployer; nil (no owner) if deployed some other way
	pendingOwner  address          // set by TransferOwnership, made owner by AcceptOwnership
	used          avl.Tree         // address + ":" + commitment -> true, both kinds
	// testSession makes tests see every call as session-signed (no test hook sets one).
	testSession bool
)

// The deployer owns the realm: deploy from the multisig that should own it.
func init(cur realm) {
	if cur.Previous().IsUserCall() {
		owner = ownable.NewWithAddress(cur.Previous().Address())
	}
}

// Offer posts a game open for validFor minutes. The stake is the ugnot sent
// with the call. A non-empty opponent makes the offer private. commitment is
// the lowercase hex sha256 of a secret passphrase, revealed after Accept.
func Offer(cur realm, opponent address, validFor int, commitment string, maxFee int64) int {
	noSession("Offer")
	stake := received(cur)
	caller := cur.Previous().Address()
	if opponent == caller {
		panic("cannot challenge yourself")
	}
	if errs := validateOffer(stake, validFor, opponent, commitment); len(errs) > 0 {
		panic(errs[0])
	}
	// The fee is snapshotted into the game: maxFee is the most the creator
	// agreed to, so a fee raised while the offer was in flight is refused.
	if fee > maxFee {
		panic("the house fee is " + gnot(fee) + ", above your maximum of " + gnot(maxFee))
	}
	useCommitment(caller, commitment)
	nextID++
	g := &Game{
		ID:        nextID,
		Creator:   caller,
		Opponent:  opponent,
		Stake:     stake,
		Fee:       fee,
		ExpiresAt: time.Now().Add(time.Duration(validFor) * time.Minute),

		Commitment: commitment,
	}
	games.Set(key(g.ID), g)
	active.Set(key(g.ID), g)
	return g.ID
}

// validateOffer returns every rule an offer breaks. Offer panics with the
// first; the "new" page lists them all before anyone signs.
func validateOffer(stake int64, validFor int, opponent address, commitment string) []string {
	var errs []string
	if stake < minStake {
		errs = append(errs, "stake below minimum of "+gnot(minStake))
	}
	if stake <= fee {
		errs = append(errs, "stake must exceed the house fee of "+gnot(fee))
	}
	if validFor < 1 || validFor > maxOfferTTL {
		errs = append(errs, "validFor must be between 1 and 60 minutes")
	}
	// IsValid also accepts other spellings of an address, which would never
	// match the canonical one Accept compares against.
	if opponent != "" && !canonical(opponent) {
		errs = append(errs, "invalid opponent address (use the lower-case g1… form)")
	}
	if !isHexSHA256(commitment) {
		errs = append(errs, "commitment must be 64 lowercase hex chars (sha256 of your passphrase)")
	}
	return errs
}

// Accept joins an open offer by sending exactly its stake. seedCommitment is
// the lowercase hex sha256 of a secret seed, revealed after the creator's
// passphrase. The creator then has 90s to Reveal.
func Accept(cur realm, id int, seedCommitment string) {
	noSession("Accept")
	stake := received(cur)
	caller := cur.Previous().Address()
	g := mustGet(id)
	if g.Status != Open {
		panic("game is not open")
	}
	if !time.Now().Before(g.ExpiresAt) {
		panic("offer expired")
	}
	if caller == g.Creator {
		panic("cannot accept your own offer")
	}
	if g.Opponent != "" && caller != g.Opponent {
		panic("offer is reserved for another player")
	}
	if stake != g.Stake {
		panic("must send exactly " + strconv.FormatInt(g.Stake, 10) + denom)
	}
	if !isHexSHA256(seedCommitment) {
		panic("seedCommitment must be 64 lowercase hex chars (sha256 of your seed)")
	}
	useCommitment(caller, seedCommitment)
	g.Acceptor = caller
	g.SeedCommitment = seedCommitment
	g.Status = Playing
	g.LastMove = time.Now() // Turn stays 0 until Reveal
}

// Reveal discloses the creator's passphrase. It must come within 90s of
// Accept; the acceptor then has 90s to RevealSeed.
func Reveal(cur realm, id int, passphrase string) {
	noCoins()
	g := mustGet(id)
	if g.Status != Playing || g.Turn != 0 || g.Revealed {
		panic("game is not awaiting the creator's reveal")
	}
	if cur.Previous().Address() != g.Creator {
		panic("only the creator can reveal")
	}
	if time.Now().After(g.deadline()) {
		panic("reveal clock ran out")
	}
	if len(passphrase) > 128 {
		panic("passphrase longer than 128 bytes")
	}
	if sha256Hex(passphrase) != g.Commitment {
		panic("passphrase does not match the commitment")
	}
	g.Passphrase = passphrase
	g.Revealed = true
	g.LastMove = time.Now()
}

// RevealSeed discloses the acceptor's seed, which with the creator's
// passphrase picks the first mover. It must come within 90s of Reveal.
func RevealSeed(cur realm, id int, seed string) {
	noCoins()
	g := mustGet(id)
	if g.Status != Playing || g.Turn != 0 || !g.Revealed {
		panic("game is not awaiting the acceptor's seed")
	}
	if cur.Previous().Address() != g.Acceptor {
		panic("only the acceptor can reveal the seed")
	}
	if time.Now().After(g.deadline()) {
		panic("reveal clock ran out")
	}
	if sha256Hex(seed) != g.SeedCommitment {
		panic("seed does not match the commitment")
	}
	g.Turn = firstMover(g.Passphrase, seed, g)
	g.LastMove = time.Now()
}

// firstMover draws 1 (creator) or 2 (acceptor) from both secrets.
func firstMover(passphrase, seed string, g *Game) byte {
	h := sha256.Sum256([]byte(strings.Join([]string{
		passphrase, seed, strconv.Itoa(g.ID), g.Creator.String(), g.Acceptor.String(),
	}, "|")))
	return 1 + h[0]&1
}

// Play drops a piece in column (1-7). move is the game's move count the
// player saw (Moves before this piece): a resent or delayed move that the game
// has moved past is refused instead of being played on a later turn.
func Play(cur realm, id, column, move int) {
	noCoins()
	g := mustGet(id)
	if g.Status != Playing {
		panic("game is not in progress")
	}
	if g.Turn == 0 {
		panic("waiting for the creator to reveal")
	}
	if cur.Previous().Address() != g.player(g.Turn) {
		panic("not your turn")
	}
	if time.Now().After(g.deadline()) {
		panic("move clock ran out")
	}
	if move != g.Moves {
		panic("stale move: the game is at move " + strconv.Itoa(g.Moves))
	}
	if column < 1 || column > cols {
		panic("column must be between 1 and 7")
	}
	r := g.Board.drop(column-1, g.Turn)
	if r < 0 {
		panic("column is full")
	}
	g.Moves++
	g.LastCol, g.LastRow = column-1, r
	switch {
	case g.Board.wins(column-1, r):
		settleWin(cur, g, g.player(g.Turn))
	case g.Moves == cols*rows:
		settleDraw(cur, g)
	default:
		g.Turn = 3 - g.Turn
		g.LastMove = time.Now()
	}
}

// ClaimTimeout settles a game whose move clock ran out. Anyone may call it.
func ClaimTimeout(cur realm, id int) {
	noCoins()
	g := mustGet(id)
	if g.Status != Playing {
		panic("game is not in progress")
	}
	if !time.Now().After(g.deadline()) {
		panic("move clock has not run out")
	}
	if g.Turn == 0 { // whoever did not reveal in time forfeits
		if g.Revealed {
			settleWin(cur, g, g.Creator)
		} else {
			settleWin(cur, g, g.Acceptor)
		}
		return
	}
	if g.Moves == 0 {
		settleVoid(cur, g)
		return
	}
	settleWin(cur, g, g.player(3-g.Turn))
}

// Resign concedes a game in progress.
func Resign(cur realm, id int) {
	noCoins()
	noSession("Resign")
	g := mustGet(id)
	if g.Status != Playing {
		panic("game is not in progress")
	}
	switch cur.Previous().Address() {
	case g.Creator:
		settleWin(cur, g, g.Acceptor)
	case g.Acceptor:
		settleWin(cur, g, g.Creator)
	default:
		panic("not a player in this game")
	}
}

// Cancel withdraws an open offer and refunds the creator. The creator may
// cancel at any time; anyone may once the offer has expired.
func Cancel(cur realm, id int) {
	noCoins()
	g := mustGet(id)
	if g.Status != Open {
		panic("game is not open")
	}
	if cur.Previous().Address() != g.Creator && time.Now().Before(g.ExpiresAt) {
		panic("only the creator can cancel an unexpired offer")
	}
	finish(g, Cancelled)
	send(cur, g.Creator, g.Stake)
}

// SetFee changes the flat house fee, in ugnot, for new offers. Games already
// offered keep the fee they were created with.
func SetFee(cur realm, amount int64) {
	noCoins()
	noSession("SetFee")
	owner.AssertOwnedBy(cur.Previous().Address())
	// Capped so the owner can't raise the fee to take most of a stake by
	// changing it just before an offer lands.
	if amount < 0 || amount > feeCap {
		panic("fee must be between 0 and " + gnot(feeCap))
	}
	fee = amount
}

// WithdrawFees sends all collected fees to to.
func WithdrawFees(cur realm, to address) {
	noCoins()
	noSession("WithdrawFees")
	owner.AssertOwnedBy(cur.Previous().Address())
	amount := feesCollected
	feesCollected = 0
	send(cur, to, amount)
}

// TransferOwnership names the next owner, who becomes owner by calling
// AcceptOwnership. Two steps, so a mistyped or non-canonical address can
// never strand ownership (and the fees): only an address that signs can
// accept, and it is recorded as it signs.
func TransferOwnership(cur realm, newOwner address) {
	noCoins()
	noSession("TransferOwnership")
	owner.AssertOwnedBy(cur.Previous().Address())
	if !canonical(newOwner) {
		panic("invalid address (use the lower-case g1… form)")
	}
	pendingOwner = newOwner
}

// AcceptOwnership completes a TransferOwnership; only the named address may call it.
func AcceptOwnership(cur realm) {
	noCoins()
	noSession("AcceptOwnership")
	caller := cur.Previous().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("no ownership transfer pending for this address")
	}
	owner = ownable.NewWithAddress(caller)
	pendingOwner = ""
}

// useCommitment records a commitment for addr, refusing one it already used:
// a revealed secret is public, so reusing it hands the other side the draw.
// Keyed by address, so nobody can block another player's commitment.
func useCommitment(addr address, commitment string) {
	k := addr.String() + ":" + commitment
	if used.Has(k) {
		panic("commitment already used: generate a fresh secret")
	}
	used.Set(k, true)
}

// received returns the ugnot sent with a direct user call. OriginSend only
// describes a real payment to this realm when the caller is an EOA using
// maketx call; see docs/resources/effective-gno.md.
func received(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("send exactly one " + denom + " coin")
	}
	return sent[0].Amount
}

// noCoins guards calls that take no payment: coins sent with them would be
// stuck in the realm.
func noCoins() {
	if len(unsafe.OriginSend()) != 0 {
		panic("this function does not accept coins")
	}
}

// noSession refuses calls signed by an account session key.
func noSession(action string) {
	if _, _, _, ok := runtime.GetSessionInfo(); ok || testSession {
		panic(action + " needs the account's own key, not a session key")
	}
}

func sha256Hex(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

func isHexSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

func settleWin(cur realm, g *Game, winner address) {
	loser := g.Creator
	if winner == g.Creator {
		loser = g.Acceptor
	}
	pot := 2 * g.Stake
	finish(g, Won)
	g.Winner = winner
	feesCollected += g.Fee
	w := statsOf(winner)
	w.Games++
	w.Wins++
	w.GnotWon += g.Stake - g.Fee
	topWins = bump(topWins, winner, int64(w.Wins))
	topGnot = bump(topGnot, winner, w.GnotWon)
	statsOf(loser).Games++
	send(cur, winner, pot-g.Fee)
}

func settleDraw(cur realm, g *Game) {
	finish(g, Draw)
	for _, p := range []address{g.Creator, g.Acceptor} {
		s := statsOf(p)
		s.Games++
		s.Draws++
		send(cur, p, g.Stake)
	}
}

func settleVoid(cur realm, g *Game) {
	finish(g, Void)
	send(cur, g.Creator, g.Stake)
	send(cur, g.Acceptor, g.Stake)
}

// leader is one leaderboard row. The boards are kept at settlement so Render
// never walks every player's stats.
type leader struct {
	Addr  address
	Score int64
}

var topWins, topGnot []leader // highest first, at most topN

const topN = 10

// bump moves addr to its new score in board. Scores only grow, so a player
// already listed can only move up; ties keep the earlier holder first.
func bump(board []leader, addr address, score int64) []leader {
	for i, l := range board {
		if l.Addr == addr {
			board = append(board[:i], board[i+1:]...)
			break
		}
	}
	i := len(board)
	for i > 0 && board[i-1].Score < score {
		i--
	}
	if i >= topN {
		return board
	}
	board = append(board, leader{})
	copy(board[i+1:], board[i:])
	board[i] = leader{addr, score}
	if len(board) > topN {
		board = board[:topN]
	}
	return board
}

func finish(g *Game, s Status) {
	g.Status = s
	active.Remove(key(g.ID))
}

func send(cur realm, to address, amount int64) {
	if amount == 0 {
		return
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.Coins{{denom, amount}})
}

func (g *Game) player(turn byte) address {
	if turn == 1 {
		return g.Creator
	}
	return g.Acceptor
}

func (g *Game) deadline() time.Time { return g.LastMove.Add(moveTimeout) }

func statsOf(addr address) *Stats {
	if v := stats.Get(addr.String()); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	stats.Set(addr.String(), s)
	return s
}

// key zero-pads ids so avl iteration order matches creation order.
func key(id int) string {
	s := strconv.Itoa(id)
	if len(s) < 10 {
		s = strings.Repeat("0", 10-len(s)) + s
	}
	return s
}

func get(id int) *Game {
	if v := games.Get(key(id)); v != nil {
		return v.(*Game)
	}
	return nil
}

func mustGet(id int) *Game {
	g := get(id)
	if g == nil {
		panic("game not found")
	}
	return g
}

package connect4_v4

import (
	"strconv"
	"strings"
	"time"
)

// GameJSON returns {"now":<unix>,"game":<game>|null}. It is a read-only
// accessor for clients querying over vm/qeval; now is the block time.
func GameJSON(id int) string {
	var b strings.Builder
	writeNow(&b)
	b.WriteString(`,"game":`)
	if g := get(id); g != nil {
		writeGame(&b, g)
	} else {
		b.WriteString("null")
	}
	b.WriteString("}")
	return b.String()
}

// ActiveJSON returns {"now":<unix>,"fee":<ugnot>,"games":[...]}: the house fee
// for new offers, then Open and Playing games in id order, skipping offset and
// returning at most limit (clamped to 1-100).
func ActiveJSON(offset, limit int) string {
	if offset < 0 {
		offset = 0
	}
	if limit < 1 {
		limit = 1
	}
	if limit > 100 {
		limit = 100
	}
	var b strings.Builder
	writeNow(&b)
	writeNum(&b, "fee", fee)
	b.WriteString(`,"games":[`)
	n := 0
	active.IterateByOffset(offset, limit, func(_ string, v any) bool {
		if n > 0 {
			b.WriteString(",")
		}
		writeGame(&b, v.(*Game))
		n++
		return false
	})
	b.WriteString("]}")
	return b.String()
}

func writeNow(b *strings.Builder) {
	b.WriteString(`{"now":`)
	b.WriteString(strconv.FormatInt(time.Now().Unix(), 10))
}

// writeGame emits one game. Every stored string is validated on write
// (addresses by IsValid, the commitment as hex), so Quote is defence in depth.
func writeGame(b *strings.Builder, g *Game) {
	turnPlayer := ""
	deadline := int64(0)
	if g.Status == Playing {
		deadline = g.deadline().Unix()
		if g.Turn != 0 {
			turnPlayer = g.player(g.Turn).String()
		}
	}
	b.WriteString(`{"id":`)
	b.WriteString(strconv.Itoa(g.ID))
	writeStr(b, "creator", g.Creator.String())
	writeStr(b, "opponent", g.Opponent.String())
	writeStr(b, "acceptor", g.Acceptor.String())
	writeNum(b, "stake", g.Stake)
	writeNum(b, "fee", g.Fee)
	writeNum(b, "expiresAt", g.ExpiresAt.Unix())
	writeStr(b, "commitment", g.Commitment)
	writeStr(b, "seedCommitment", g.SeedCommitment)
	// revealed: the creator's passphrase is out; with turn 0 the game waits for RevealSeed.
	if g.Revealed {
		b.WriteString(`,"revealed":true`)
	} else {
		b.WriteString(`,"revealed":false`)
	}
	b.WriteString(`,"board":"`)
	for c := 0; c < cols; c++ {
		for r := 0; r < rows; r++ {
			b.WriteByte('0' + g.Board[c][r])
		}
	}
	b.WriteString(`"`)
	writeNum(b, "turn", int64(g.Turn))
	writeStr(b, "turnPlayer", turnPlayer)
	writeNum(b, "moves", int64(g.Moves))
	writeNum(b, "lastCol", int64(g.LastCol))
	writeNum(b, "lastRow", int64(g.LastRow))
	writeNum(b, "deadline", deadline)
	writeStr(b, "status", g.Status.String())
	writeStr(b, "winner", g.Winner.String())
	b.WriteString("}")
}

// writeStr and writeNum append `,"k":v`; the caller writes the first field.
func writeStr(b *strings.Builder, k, v string) {
	b.WriteString(`,"`)
	b.WriteString(k)
	b.WriteString(`":`)
	b.WriteString(strconv.Quote(v))
}

func writeNum(b *strings.Builder, k string, v int64) {
	b.WriteString(`,"`)
	b.WriteString(k)
	b.WriteString(`":`)
	b.WriteString(strconv.FormatInt(v, 10))
}

// LeadersJSON returns {"wins":[...],"gnot":[...]}: the top-10 boards (most
// games won, most ugnot won) kept at settlement, highest first. Each entry is
// {"addr":<address>,"score":<int>}.
func LeadersJSON() string {
	var b strings.Builder
	b.WriteString(`{"wins":`)
	writeLeaders(&b, topWins)
	b.WriteString(`,"gnot":`)
	writeLeaders(&b, topGnot)
	b.WriteString("}")
	return b.String()
}

func writeLeaders(b *strings.Builder, board []leader) {
	b.WriteString("[")
	for i, l := range board {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"addr":`)
		b.WriteString(strconv.Quote(l.Addr.String()))
		writeNum(b, "score", l.Score)
		b.WriteString("}")
	}
	b.WriteString("]")
}

package connect4_v4

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"net/url"
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/svg/v0"
)

// lobbyRows caps the games the lobby lists, so Render stays within query gas
// however many games are open; clients page through ActiveJSON instead.
const lobbyRows = 50

// Board colours. gnoweb only embeds SVG as data-URI images, so each column is
// its own image, wrapped in its Play link while the game is being played.
const (
	red            = "#e53935"
	yellow         = "#fdd835"
	hole           = "#ffffff"
	boardBlue      = "#1565c0"
	lastMoveStroke = "#212121"
	winStroke      = "#00e676"
	cellPx         = 48
	headerPx       = 20
)

var pieceColor = [...]string{hole, red, yellow}
var pieceName = [...]string{"empty", "red", "yellow"}

// Render serves "" (lobby and leaderboards), "new" (offer form) and
// "game/<id>" (one game with every action its state allows).
// Everything written comes from realm state or from query values that have
// been validated and re-formatted; raw path input is never echoed.
func Render(path string) string {
	p, query, _ := strings.Cut(path, "?")
	switch {
	case p == "":
		return renderLobby()
	case p == "new":
		return renderNew(query)
	}
	if s, ok := strings.CutPrefix(p, "game/"); ok {
		if id, err := strconv.Atoi(s); err == nil {
			if g := get(id); g != nil {
				return renderGame(g)
			}
		}
	}
	return "# Not found\n"
}

// pageURL links to one of this realm's Render pages. The realm path is read
// at runtime, like txlink does, so links work wherever the realm is deployed.
func pageURL(page string) string {
	base := strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
	if page == "" {
		return base
	}
	return base + ":" + page
}

func gameLink(base string, id int) string {
	return "[#" + strconv.Itoa(id) + "](" + base + ":game/" + strconv.Itoa(id) + ")"
}

func renderLobby() string {
	now := time.Now()
	base := pageURL("")
	var open, live strings.Builder
	// Only rows actually written count toward lobbyRows: expired offers nobody
	// cancelled must not crowd out live games.
	shown := 0
	active.Iterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		switch {
		case g.Status == Open && now.Before(g.ExpiresAt):
			open.WriteString("| " + gameLink(base, g.ID) + " | " + gnot(g.Stake) + " | " + gnot(g.Fee) + " | " + g.Creator.String() + " | " + openTo(g) +
				" | " + remaining(g.ExpiresAt.Sub(now)) + " | [Accept](" + acceptURL(g) + ") |\n")
		case g.Status == Playing:
			live.WriteString("| " + gameLink(base, g.ID) + " | " + gnot(2*g.Stake) + " | " + onTurn(g) + " | " + clockLeft(g, now) + " |\n")
		default:
			return false
		}
		shown++
		return shown == lobbyRows
	})

	var b strings.Builder
	b.WriteString("# Connect 4\n\n")
	b.WriteString("Both players stake the same amount; the winner takes the pot minus the house fee shown on each offer " +
		"(" + gnot(fee) + " for new offers). " +
		"90s per move: run out and you forfeit. If the first mover never moves, both stakes are refunded.\n\n")
	b.WriteString("**[Post an offer](" + base + ":new)** · open a game below to play it\n\n")
	b.WriteString("## Open offers\n\n")
	if open.Len() == 0 {
		b.WriteString("No open offers.\n\n")
	} else {
		b.WriteString("| Game | Stake | Fee | Creator | For | Expires in | |\n|---|---|---|---|---|---|---|\n" + open.String() + "\n")
	}
	b.WriteString("## Live games\n\n")
	if live.Len() == 0 {
		b.WriteString("No games in progress.\n\n")
	} else {
		b.WriteString("| Game | Pot | Turn | Time left |\n|---|---|---|---|\n" + live.String() + "\n")
	}
	if shown == lobbyRows {
		b.WriteString("Showing the first " + strconv.Itoa(lobbyRows) + " games.\n\n")
	}
	b.WriteString("## Most games won\n\n")
	b.WriteString(leaderboard(topWins, func(v int64) string { return strconv.FormatInt(v, 10) }))
	b.WriteString("## Most gnot won\n\n")
	b.WriteString(leaderboard(topGnot, gnot))
	return b.String()
}

// renderNew shows the offer form and, once submitted, a single Offer link
// with the stake and every argument prefilled (gnoweb cannot edit .send).
func renderNew(query string) string {
	var b strings.Builder
	b.WriteString("# Post an offer\n\n[← Lobby](" + pageURL("") + ")\n\n")
	b.WriteString("Generate a fresh random passphrase for every offer and keep it: " +
		"once someone accepts you have 90s to reveal it, or you forfeit. " +
		"A guessable one lets an opponent work out who moves first. " +
		"Paste only its sha256 below, never the passphrase itself:\n\n" +
		"    pass=$(openssl rand -hex 32); echo \"$pass\"\n" +
		"    printf %s \"$pass\" | shasum -a 256\n\n")
	b.WriteString(`<gno-form path="new">
<gno-input name="stake" type="text" placeholder="Stake in GNOT, e.g. 10 (min 1)" />
<gno-input name="validFor" type="number" placeholder="Minutes the offer stays open, 1-60 (default 15)" />
<gno-input name="opponent" type="text" placeholder="Opponent address (optional, leave empty for anyone)" />
<gno-input name="commitment" type="text" placeholder="sha256 of your passphrase (64 hex chars)" />
</gno-form>

`)
	if query == "" {
		return b.String()
	}

	q, err := url.ParseQuery(query)
	if err != nil {
		return b.String() + "Could not read the form.\n"
	}
	// Parse first; the offer rules themselves live in validateOffer so this
	// page and Offer cannot drift apart.
	var errs []string
	stake, ok := parseGNOT(q.Get("stake"))
	if !ok {
		errs = append(errs, "stake must be a GNOT amount with at most 6 decimals, e.g. 10 or 2.5")
	}
	validFor := 15
	if v := q.Get("validFor"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil {
			errs = append(errs, "validFor must be a whole number of minutes")
		}
		validFor = n
	}
	opponent := address(q.Get("opponent"))
	commitment := q.Get("commitment")
	if len(errs) == 0 {
		errs = validateOffer(stake, validFor, opponent, commitment)
	}
	if len(errs) > 0 {
		b.WriteString("**Fix the following:**\n\n")
		for _, e := range errs {
			b.WriteString("- " + e + "\n")
		}
		return b.String()
	}

	b.WriteString("## Ready\n\n")
	who := "anyone"
	if opponent != "" {
		who = opponent.String()
	}
	b.WriteString("Stake " + gnot(stake) + ", open to " + who + " for " + strconv.Itoa(validFor) + " min, " +
		"house fee at most " + gnot(fee) + ", commitment `" + commitment + "`. " +
		"Check it is the sha256 of your own passphrase before signing.\n\n")
	b.WriteString("**[Post offer for " + gnot(stake) + "](" + txlink.NewLink("Offer").
		AddArgs("opponent", opponent.String(), "validFor", strconv.Itoa(validFor), "commitment", commitment,
			"maxFee", strconv.FormatInt(fee, 10)).
		SetSend(strconv.FormatInt(stake, 10)+denom).URL() + ")**\n")
	return b.String()
}

func renderGame(g *Game) string {
	now := time.Now()
	var b strings.Builder
	id := strconv.Itoa(g.ID)
	b.WriteString("# Game #" + id + " — " + g.Status.String() + "\n\n[← Lobby](" + pageURL("") + ")\n\n")
	b.WriteString("🔴 " + g.Creator.String() + "  \n🟡 " + orNone(g.Acceptor) + "  \n")
	b.WriteString("Stake: " + gnot(g.Stake) + " each · fee " + gnot(g.Fee) + "\n\n")
	b.WriteString(boardView(g, now) + "\n\n")

	switch g.Status {
	case Open:
		cancel := "[Cancel offer](" + txlink.NewLink("Cancel").AddArgs("id", id).URL() + ")"
		if now.Before(g.ExpiresAt) {
			b.WriteString("Open offer for " + openTo(g) + ", expires in " + remaining(g.ExpiresAt.Sub(now)) + ".\n\n")
			b.WriteString("**[Accept for " + gnot(g.Stake) + "](" + acceptURL(g) + ")** with the sha256 of a fresh random seed " +
				"(`openssl rand -hex 32`). Keep the seed: you reveal it after the creator, within 90s, or forfeit.\n\n")
			b.WriteString(cancel + " (creator)\n")
		} else {
			b.WriteString("This offer expired. Anyone can " + cancel + " to refund the creator.\n")
		}
	case Playing:
		left := g.deadline().Sub(now)
		claim := "Clock ran out: **[Claim timeout](" + txlink.NewLink("ClaimTimeout").AddArgs("id", id).URL() + ")**\n\n"
		resign := "[Resign](" + txlink.NewLink("Resign").AddArgs("id", id).URL() + ")\n"
		if g.Turn == 0 {
			if !g.Revealed {
				b.WriteString("Waiting for the creator to reveal the passphrase.\n\n")
			} else {
				b.WriteString("Passphrase revealed. Waiting for the acceptor to reveal the seed.\n\n")
			}
			if left >= 0 {
				b.WriteString("Time left: " + remaining(left) + "\n\n")
				if !g.Revealed {
					b.WriteString("**[Reveal](" + txlink.NewLink("Reveal").AddArgs("id", id, "passphrase", "").URL() + ")** (creator)\n\n")
				} else {
					b.WriteString("**[Reveal seed](" + txlink.NewLink("RevealSeed").AddArgs("id", id, "seed", "").URL() + ")** (acceptor)\n\n")
				}
			} else {
				b.WriteString(claim)
			}
			b.WriteString(resign)
			break
		}
		b.WriteString("Turn: " + [...]string{"", "🔴", "🟡"}[g.Turn] + " " + g.player(g.Turn).String() + "\n\n")
		if left >= 0 {
			b.WriteString("Time left: " + remaining(left) + " · click a column to drop your piece\n\n")
		} else {
			b.WriteString(claim)
		}
		b.WriteString(resign)
	case Won:
		b.WriteString("Winner: " + g.Winner.String() + ", paid " + gnot(2*g.Stake-g.Fee) + ".\n")
	case Draw:
		b.WriteString("Draw: both stakes refunded.\n")
	case Void:
		b.WriteString("Void: the first mover never moved, both stakes refunded.\n")
	case Cancelled:
		b.WriteString("Cancelled: stake refunded to the creator.\n")
	}
	return b.String()
}

// boardView draws the board. While a move can be played it is 7 column
// images, each wrapped in its Play link (gnoweb lays linked images out side by
// side). Otherwise it is one image of all 7 columns, since gnoweb stacks bare
// images vertically. The last move gets a dark ring, a winning line a green one.
func boardView(g *Game, now time.Time) string {
	playable := g.Status == Playing && g.Turn != 0 && !now.After(g.deadline())
	var win [cols][rows]bool
	if g.Status == Won && g.Moves > 0 {
		for _, cell := range g.Board.winLine(g.LastCol, g.LastRow) {
			win[cell[0]][cell[1]] = true
		}
	}
	const height = headerPx + rows*cellPx
	if !playable {
		canvas := svg.NewCanvas(cols*cellPx, height).WithViewBox(0, 0, cols*cellPx, height)
		alt := "board:"
		for c := 0; c < cols; c++ {
			alt += " " + drawColumn(canvas, g, &win, c, c*cellPx) + ";"
		}
		return canvas.Render(alt)
	}
	id := strconv.Itoa(g.ID)
	var b strings.Builder
	for c := 0; c < cols; c++ {
		canvas := svg.NewCanvas(cellPx, height).WithViewBox(0, 0, cellPx, height)
		alt := drawColumn(canvas, g, &win, c, 0)
		b.WriteString("[" + canvas.Render(alt) + "](" +
			txlink.NewLink("Play").AddArgs("id", id, "column", strconv.Itoa(c+1), "move", strconv.Itoa(g.Moves)).URL() + ")")
	}
	return b.String()
}

// drawColumn draws column c at horizontal offset x and returns its alt text.
func drawColumn(canvas *svg.Canvas, g *Game, win *[cols][rows]bool, c, x int) string {
	bg := svg.NewRectangle(x, 0, cellPx, headerPx+rows*cellPx, boardBlue)
	bg.Attr.Class = "col"
	canvas.Append(bg, svg.NewText(x+cellPx/2-4, 15, strconv.Itoa(c+1), hole))
	alt := "column " + strconv.Itoa(c+1) + ":"
	for r := 0; r < rows; r++ {
		disc := svg.NewCircle(x+cellPx/2, headerPx+(rows-1-r)*cellPx+cellPx/2, cellPx/2-5, pieceColor[g.Board[c][r]])
		switch {
		case win[c][r]:
			disc.Attr.Stroke, disc.Attr.StrokeWidth = winStroke, "5"
		case g.Moves > 0 && c == g.LastCol && r == g.LastRow:
			disc.Attr.Stroke, disc.Attr.StrokeWidth = lastMoveStroke, "3"
		}
		canvas.Append(disc)
		alt += " " + pieceName[g.Board[c][r]]
	}
	return alt
}

// onTurn names who the game waits for.
func onTurn(g *Game) string {
	switch {
	case g.Turn != 0:
		return g.player(g.Turn).String()
	case g.Revealed:
		return g.Acceptor.String() + " (reveal seed)"
	}
	return g.Creator.String() + " (reveal)"
}

// clockLeft is the time left on the move clock, or "clock ran out". Play is
// still accepted in the deadline block itself, so zero left is not expired.
func clockLeft(g *Game, now time.Time) string {
	if now.After(g.deadline()) {
		return "clock ran out"
	}
	return remaining(g.deadline().Sub(now))
}

func acceptURL(g *Game) string {
	return txlink.NewLink("Accept").AddArgs("id", strconv.Itoa(g.ID), "seedCommitment", "").
		SetSend(strconv.FormatInt(g.Stake, 10) + denom).URL()
}

func digits(s string) bool {
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func openTo(g *Game) string {
	if g.Opponent != "" {
		return g.Opponent.String()
	}
	return "anyone"
}

// parseGNOT parses a decimal GNOT amount ("10", "2.5") into ugnot.
func parseGNOT(s string) (int64, bool) {
	whole, frac, _ := strings.Cut(s, ".")
	if whole == "" || len(whole) > 12 || len(frac) > 6 {
		return 0, false
	}
	if !digits(whole) || !digits(frac) {
		return 0, false
	}
	w, _ := strconv.ParseInt(whole, 10, 64)
	f, _ := strconv.ParseInt(frac+strings.Repeat("0", 6-len(frac)), 10, 64)
	return w*1_000_000 + f, true
}

// leaderboard renders a board kept at settlement (topWins, topGnot).
func leaderboard(board []leader, format func(int64) string) string {
	if len(board) == 0 {
		return "No finished games yet.\n\n"
	}
	var b strings.Builder
	b.WriteString("| # | Player | |\n|---|---|---|\n")
	for i, r := range board {
		b.WriteString("| " + strconv.Itoa(i+1) + " | " + r.Addr.String() + " | " + format(r.Score) + " |\n")
	}
	b.WriteString("\n")
	return b.String()
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(ugnot int64) string {
	whole := strconv.FormatInt(ugnot/1_000_000, 10)
	frac := ugnot % 1_000_000
	if frac == 0 {
		return whole + " GNOT"
	}
	f := strconv.FormatInt(frac, 10)
	f = strings.TrimRight(strings.Repeat("0", 6-len(f))+f, "0")
	return whole + "." + f + " GNOT"
}

func remaining(d time.Duration) string { return d.Truncate(time.Second).String() }

func orNone(a address) string {
	if a == "" {
		return "waiting for opponent"
	}
	return a.String()
}

package connect4_v4

import (
	"encoding/base64"
	"strconv"
	"strings"
	"testing"
	"time"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestLeaderboardTopTen(t *testing.T) {
	reset()
	for i := 1; i <= 12; i++ {
		topWins = bump(topWins, testutils.TestAddress("p"+strconv.Itoa(i)), int64(i))
	}
	out := leaderboard(topWins, func(v int64) string { return strconv.FormatInt(v, 10) })
	uassert.True(t, strings.HasPrefix(strings.Split(out, "\n")[2], "| 1 | "+testutils.TestAddress("p12").String()+" | 12 |"))
	uassert.True(t, strings.Contains(out, "| 10 | "+testutils.TestAddress("p3").String()+" | 3 |"))
	uassert.False(t, strings.Contains(out, testutils.TestAddress("p2").String()))
}

func TestGamePageShowsActionsForEveryState(cur realm, t *testing.T) {
	reset()
	contains := func(out string, want ...string) {
		for _, w := range want {
			uassert.True(t, strings.Contains(out, w), "missing "+w+" in:\n"+out)
		}
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	pay(stake)
	id := Offer(cross(cur), "", 10, commit(), fee)
	page := "game/" + strconv.Itoa(id)
	contains(Render(page), "func=Accept", ".send=10000000ugnot", "func=Cancel", "Open offer")

	g := mustGet(id)
	g.ExpiresAt = time.Now().Add(-time.Second)
	out := Render(page)
	contains(out, "expired", "func=Cancel")
	uassert.False(t, strings.Contains(out, "func=Accept"))

	g, p := accepted(cur)
	page = "game/" + strconv.Itoa(g.ID)
	contains(Render(page), "Waiting for", "func=Reveal", "func=Resign")

	testing.SetRealm(testing.NewUserRealm(alice))
	pay(0)
	revealBoth(cur, g, p)
	contains(Render(page), "func=Play", "column=7", "func=Resign", "Turn:")

	testing.SetRealm(testing.NewUserRealm(alice))
	pay(0)
	Resign(cross(cur), g.ID)
	contains(Render(page), "Winner", bob.String(), gnot(2*stake-fee))

	for status, want := range map[Status]string{
		Draw:      "both stakes refunded",
		Void:      "both stakes refunded",
		Cancelled: "refunded to the creator",
	} {
		g.Status = status
		contains(Render(page), want)
	}
}

func TestLobbyLinksEveryGameToItsPage(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	pay(stake)
	id := Offer(cross(cur), "", 10, commit(), fee)
	g, _ := accepted(cur)
	// Render as if deployed elsewhere: links must follow the realm's real path.
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/nym-mikecito001/connect4"))
	out := Render("")
	base := "(/r/nym-mikecito001/connect4:"
	uassert.True(t, strings.Contains(out, base+"game/"+strconv.Itoa(id)+")"), out)
	uassert.True(t, strings.Contains(out, base+"game/"+strconv.Itoa(g.ID)+")"), out)
	uassert.True(t, strings.Contains(out, base+"new)"), out)
	uassert.False(t, strings.Contains(out, "samcrew"), "links must not hardcode the realm path")
}

func TestNewOfferPage(t *testing.T) {
	reset()
	c := sha256Hex("some four random words")

	out := Render("new")
	uassert.True(t, strings.Contains(out, `<gno-form path="new">`))
	uassert.False(t, strings.Contains(out, "func=Offer"))

	out = Render("new?stake=12.5&validFor=10&opponent=" + bob.String() + "&commitment=" + c)
	for _, want := range []string{"func=Offer", ".send=12500000ugnot", "validFor=10", "opponent=" + bob.String(), "commitment=" + c, "12.5 GNOT"} {
		uassert.True(t, strings.Contains(out, want), "missing "+want+" in:\n"+out)
	}

	out = Render("new?stake=3&commitment=" + c) // validFor defaults, opponent optional
	uassert.True(t, strings.Contains(out, ".send=3000000ugnot"))
	uassert.True(t, strings.Contains(out, "validFor=15"))

	for _, q := range []string{
		"stake=%3Cscript%3E&validFor=10&commitment=" + c, // not a number
		"stake=0.5&validFor=10&commitment=" + c,          // below minimum
		"stake=1.0000001&validFor=10&commitment=" + c,    // more than 6 decimals
		"stake=5&validFor=61&commitment=" + c,
		"stake=5&validFor=10&opponent=%3Cscript%3E&commitment=" + c,
		"stake=5&validFor=10&commitment=%3Cscript%3E",
		"stake=5&validFor=10",
	} {
		out := Render("new?" + q)
		uassert.False(t, strings.Contains(out, "func=Offer"), q)
		uassert.True(t, strings.Contains(out, "Fix the following"), q)
		uassert.False(t, strings.Contains(out, "<script>"), "form input echoed: "+q)
	}
}

// svgs returns the decoded SVG of every data-URI image in out, and the
// markdown that immediately wraps each image ("[" link or "" for none).
func svgs(t *testing.T, out string) (images []string, linked []bool) {
	parts := strings.Split(out, "(data:image/svg+xml;base64,")
	for i, p := range parts[1:] {
		end := strings.Index(p, ")")
		raw, err := base64.StdEncoding.DecodeString(p[:end])
		if err != nil {
			t.Fatalf("image %d is not base64: %v", i, err)
		}
		images = append(images, string(raw))
		before := parts[i]
		img := strings.LastIndex(before, "![")
		linked = append(linked, img > 0 && before[img-1] == '[')
	}
	return images, linked
}

func TestBoardIsClickableSVGColumns(cur realm, t *testing.T) {
	reset()
	g, p := accepted(cur)
	page := "game/" + strconv.Itoa(g.ID)

	// Reveal phase: the board is one image holding all 7 columns, not a link.
	out := Render(page)
	images, linked := svgs(t, out)
	uassert.Equal(t, 1, len(images))
	uassert.Equal(t, 7, strings.Count(images[0], `class="col"`))
	uassert.False(t, linked[0], "no clickable column before the reveal")
	uassert.True(t, strings.Contains(out, "![board: column 1:"), "alt text")
	uassert.False(t, strings.Contains(out, "func=Play"))

	testing.SetRealm(testing.NewUserRealm(alice))
	pay(0)
	revealBoth(cur, g, p)
	first := g.Turn
	move(cur, g, 3) // first mover drops in column 3

	out = Render(page)
	for c := 1; c <= 7; c++ {
		uassert.True(t, strings.Contains(out, "](/r/samcrew/connect4$help&func=Play&column="+strconv.Itoa(c)+"&id=") ||
			strings.Contains(out, "$help&func=Play&column="+strconv.Itoa(c)+"&id="), "column link "+strconv.Itoa(c))
	}
	images, linked = svgs(t, out)
	boardImgs := 0
	for i, img := range images {
		if strings.Contains(img, `class="col"`) {
			boardImgs++
			uassert.True(t, linked[i], "board column must be a link while playing")
		}
	}
	uassert.Equal(t, 7, boardImgs)
	col3 := images[boardIndex(images, 3)]
	uassert.True(t, strings.Contains(col3, `fill="`+[...]string{"", red, yellow}[first]+`"`), col3)
	uassert.True(t, strings.Contains(col3, `stroke="`+lastMoveStroke+`"`), "last move ring")
	uassert.True(t, strings.Contains(out, "![column 3: "+[...]string{"", "red", "yellow"}[first]), "alt text")

	// Win with four stacked in column 1: the four cells get the win ring.
	for _, c := range []int{1, 2, 1, 2, 1, 2} {
		move(cur, g, c)
	}
	move(cur, g, 1)
	uassert.Equal(t, "won", g.Status.String())
	out = Render(page)
	images, _ = svgs(t, out)
	uassert.Equal(t, 1, len(images))
	uassert.Equal(t, 4, strings.Count(images[0], `stroke="`+winStroke+`"`), images[0])
	uassert.False(t, strings.Contains(out, "func=Play"))
}

// boardIndex returns the index in images of board column c (1-based).
func boardIndex(images []string, c int) int {
	n := 0
	for i, img := range images {
		if strings.Contains(img, `class="col"`) {
			n++
			if n == c {
				return i
			}
		}
	}
	return -1
}

